      case "find" => {
        val key: Int = op(1).toInt
        println(if (t.find(key)) "yes" else "no")
        t
      }
      case _ => throw new Error("Unknown operation")
    }
  }

  trait BTree {
    def insert(x: Int): BTree
    def preorder: List[Int]
    def inorder: List[Int]
    def show: Unit = {
      println(" " + this.inorder.mkString(" "))
      println(" " + this.preorder.mkString(" "))
    }
    def find(x: Int): Boolean
  }
  object Empty extends BTree {
    def insert(x: Int): BTree = new Node(x, Empty, Empty)
