const int OP_LEN = 20;

typedef struct _node {
  int num;
  struct _node *left;
  struct _node *right;
} node;

node *tree = NULL;

node *make_node(int num)
{
  node *v = (node *)malloc(sizeof(node));
  v->num = num;
  v->left = NULL;
  v->right = NULL;
  return v;
}

void insert_body(node *tree, int num)
{
  node *l = tree->left;
  node *r = tree->right;
  if (num <= tree->num) {
    if (l == NULL)
      tree->left = make_node(num);
    else
      insert_body(l, num);
  } else {
    if (r == NULL)
      tree->right = make_node(num);
    else
      insert_body(r, num);
  }
}

void insert(int num)
{
  if (tree == NULL)
    tree = make_node(num);
  else
    insert_body(tree, num);
}

void print_tree(node *tree)
{
  if (tree == NULL) {
    printf("*");
  } else {
    printf("(%d ", tree->num);
    print_tree(tree->left);
    printf(" ");
    print_tree(tree->right);
    printf(")");
  }
}

