bool find_body(node *tree, int num)
{
  if (tree == NULL) return false;
  if (tree->num == num) return true;
  if (num <= tree->num) return find_body(tree->left, num);
  return find_body(tree->right, num);
}

bool find(int num)
{
  return find_body(tree, num);
}

