	}
	//zはparentの left か right になる
	z->parent = parent;


	auto& up
		= z->key < parent->key ?
		parent->left
		: parent->right;

	up = std::move(z);

}

template<class T>
auto find(node<T>* root, const T& value_)->node<T>* {
	if (root == nullptr)
		return nullptr;

	if (root->key == value_)
		return root;

	auto& child = value_ < root->key ? root->left : root->right;
	return find( child.get(), value_);

}

