struct Node {
	int key;
	Node* l, * p, * r;
};

Node* root, * Nil;

void insert(int key) {
	Node* x, * y, * z;
	x = root;
	y = Nil;
	z = (Node*)malloc(sizeof(Node));
	z->key = key;
	z->l = Nil;
	z->r = Nil;
	while (x != Nil) {
		y = x;
		if (x->key > z->key) {
			x = x->l;
		}
		else {
			x = x->r;
		}
	}
	z->p = y;
	if (y == Nil) {
		root = z;
	}
	else {
		if (z->key < y->key) {
			y->l = z;
		}
		else {
			y->r = z;
		}
	}

}

Node* find(Node* u, int key) {
	while (u != Nil && u->key != key) {
		if (key < u->key) {
			u = u->l;
		}
		else {
			u = u->r;
		}
	}
	return u;
}

