struct Node{
    int key;
    Node *parent;
    Node *left;
    Node *right;
};

struct Node *NIL, *root;

void init(){
    root = NIL;
}

void insert(Node* z){
    struct Node* y = NIL; // xの親
    struct Node* x = root;

    while(x != NIL){
        y = x;
        if(z->key < x->key){
            x = x->left;
        }else{
            x = x->right;
        }
    }
    z->parent = y;

    if(y == NIL){
        root = z;
    }
    else if(z->key < y->key){
        y->left = z; 
    }else{
        y->right = z;
    }
}

bool find_number(Node* x, int num){
    if(x == NIL){
        return false;
    }
    if(x->key == num){
        return true;
    }
    if(x->key < num){
        return find_number(x->right, num);
    }
    return find_number(x->left, num);
}

