	list<Node>::iterator parent,left,right;
};

class Tree{
public:
	list<Node> node_list;
	list<Node>::iterator root;
	vector<int> preorder,inorder;

	Tree(){
		root = node_list.end();
	}
	void insert(list<Node>::iterator z){
		list<Node>::iterator y = node_list.end();
		list<Node>::iterator x = root;

		while(x!=node_list.end()){
			y = x;
			if(z->key<x->key){
				x = x->left;
			}
			else{
				x = x->right;
			}
		}
		z->parent = y;
		if(y==node_list.end()){
			root = z;
		}
		else if(z->key<y->key){
			y->left = z;
		}
		else{
			y->right = z;
		}
	}
	bool find(int key,list<Node>::iterator z){
		if(z->key==key) return true;

		if(z->key>key && z->left!=node_list.end()){
			return find(key,z->left);
		}
		else if(z->key<key && z->right!=node_list.end()){
			return find(key,z->right);
		}
		return false;
	}
	bool find(int key){
		return find(key,root);
	}
	void DFS(list<Node>::iterator parent){
		preorder.push_back(parent->key);

		if(parent->left==node_list.end()){
			inorder.push_back(parent->key);
		}
		else{
			DFS(parent->left);
			inorder.push_back(parent->key);
		}

		if(parent->right!=node_list.end()){
			DFS(parent->right);
		}
	}
	void DFS(){
		preorder.clear();
		inorder.clear();
		DFS(root);
	}
};

