            tree.ShowWithPreorderWalk();
            for(int item : tree.order) {
                cout << ' ' << item;
            }
            cout << endl;
        }
        else if(cmd == "find") {
            int value; cin >> value;
            cout << (tree.HasKey(value) ? "yes" : "no") << endl;
        }
        else {
            int value; cin >> value;
            tree.Insert(value);
        }
    }
}

