    Node *x = head;
    Node *y = NIL;  //表示父节点
    while (x != NIL){
        y = x;
        if (value < x->value){
            x = x->left;
        }
        else{
            x = x->right;
        }
    }
    Node *z = new(Node);
    z->value = value;
    z->left = NIL;
    z->right = NIL;
    if (y != NIL){
        if (z->value < y->value){
            y->left = z;
        }
        else{
            y->right = z;
        }
        z->parent = y;
    } else{
        head = z;
    }
}

bool findNode(Node *root, int value ){
    if (root == NIL) return false;
    if (root->value == value) return true;
    bool left= false, right= false;
    if (root->value < value)
        right = findNode(root->right, value);
    if (root->value > value)
        left = findNode(root->left, value);
    return left || right;
}

