  if (root == NULL) {
    return false;
  }

  struct Node *node = root;

  while (node != NULL) {
    if (node->key == v) {
      return true;
    }

    if (node->key < v) {
      node = node->right;
    } else {
      node = node->left;
    }
  }

  return false;
}

