class BinarySearchTree{
    struct Node{
        int key;
        Node *right, *parent, *left;
        Node(): key(NIL), right(nullptr), parent(nullptr), left(nullptr){};
        Node(int k): key(k), right(nullptr), parent(nullptr), left(nullptr){};
    };
    Node *root, *NILL = nullptr;
public:
    BinarySearchTree(): root(nullptr){};

    void insert(int k){
        Node *y = nullptr;
        Node *x = root;
        Node *z = new Node(k);
        while(x != nullptr){
            y = x;
            if(z->key < x->key){
                x = x->left;
            }else{
                x = x->right;
            }
        }
        z->parent = y;
        if(y == nullptr)
            root = z;
        else{
            if(z->key < y->key){
                y->left = z;
            }else{
                y->right = z;
            }
        }
    }

private:
    Node* find(Node *v, int k){
        while(v != nullptr && k != v->key){
            if(k < v->key) v = v->left;
            else v = v->right;
        }
        return v;
    }

    Node* treeMinimum(Node *v){
        while(v->left != nullptr)
            v = v->left;
        return v;
    }

    Node* treeSuccesor(Node *v){
        if(v->right != nullptr) return treeMinimum(v->right);
        Node *y = v->parent;
        while(y != nullptr && v == y->right){
            v = y;
            y = y->parent;
        }
        return y;
    }

    void tDelete(Node *z){
        Node *y, *x;
        if(z->left == nullptr || z->right == nullptr)
            y = z;
        else y = treeSuccesor(z);
        if(y->left != nullptr){
            x = y->left;
        }else{
            x = y->right;
        }
        if(x != nullptr)
            x->parent = y->parent;
        if(y->parent == nullptr)
            root = x;
        else{
            if(y == y->parent->left)
                y->parent->left = x;
            else y->parent->right = x;
        }
        if(y != z){
            z->key = y->key;
        }
        delete(y);
    }

    void inOrder(Node *v){
        if(v == nullptr) return;
        inOrder(v->left);
        cout << " " << v->key;
        inOrder(v->right);
    }

    void preOrder(Node *v){
        if(v == nullptr) return;
        cout << " " << v->key;
        preOrder(v->left);
        preOrder(v->right);
    }

public:
    bool find(int x){
        Node *t = find(root, x);
        return t != nullptr;
    }

    void tDelete(int x){
        tDelete(find(root, x));
    }

    void outInOrder(){
        inOrder(root);
    }

    void outPreOrder(){
        preOrder(root);
    }

};


