#include <bits/stdc++.h>
using namespace std;
using ll = long long;
template <class T, class U> using Pa = pair<T, U>;
template <class T> using vec = vector<T>;
template <class T> using vvec = vector<vec<T>>;

template<class T>
class BinaryTree{
private:
    struct Node{
        T val;
        Node* par;
        Node* left;
        Node* right;
    };
    Node *root;
    void insert(int x,Node* now,Node* par){
        if(x < now->val){
            if(now->left != nullptr){
                insert(x,now->left,now);
            }else{
                now->left = new Node;
                now->left->val = x;
                now->left->left = nullptr;
                now->left->right = nullptr;
                now->par = par;
            }
        }else{
            if(now->right != nullptr){
                insert(x,now->right,now);
            }else{
                now->right = new Node;
                now->right->val = x;
                now->right->left = nullptr;
                now->right->right = nullptr;
            }
        }
    }

    void erase(Node* now){
        if(now->left == nullptr && now->right == nullptr){
            now = nullptr;
        }else{
            Node* c = (now->left!=nullptr? now->left:now->right);
            c->par = now->par;
            now = c;
        }
    }

    void erase(Node* now,Node* par,T x){
        if(now->val==x){
            if(now->left != nullptr && now->right != nullptr){
                now->val = now->right->val;
                erase(preorder_next(now));
            }else{
                erase(now,par,x);
            }
        }else if(x < now->val){
            if(now->left != nullptr) return erase(now->left,now,x);
        }else{
            if(now->right != nullptr) return erase(now->right,now,x);
        }
    }

    bool find(Node* now,T x){
        if(now->val == x) return true;
        if(x < now->val){
            if(now->left != nullptr) return find(now->left,x);
        }else{
            if(now->right != nullptr) return find(now->right,x);
        }
        return false;
    }

    Node* preorder_next(Node* now){
        now = now->right;
        while(now!=nullptr){
            now = now->left;
        }
        return now;
    }

    void inorder_walk(Node* now,vec<T>& v){
        if(now->left!=nullptr) inorder_walk(now->left,v);
        v.push_back(now->val);
        if(now->right!=nullptr) inorder_walk(now->right,v);
    }
    void preorder_walk(Node* now,vec<T>& v){
        v.push_back(now->val);
        if(now->left!=nullptr) preorder_walk(now->left,v);
        if(now->right!=nullptr) preorder_walk(now->right,v);
    }


public:
    BinaryTree():root(nullptr){}
    void insert(T x){
        if(root==nullptr){
            root = new Node;
            root->val = x;
            root->left = nullptr;
            root->right = nullptr;
            root->par = nullptr;
        }else{
            insert(x,root,nullptr);
        }
    }

    void erase(T x){
        erase(root,nullptr,x);
    }

    bool find(T x){
        if(root==nullptr) return false;
        else return find(root,x);
    }

    vec<T> inorder_walk(){
        if(root==nullptr) return {};
        vec<T> res;
        inorder_walk(root,res);
        return res;
    }
    vec<T> preorder_walk(){
        if(root==nullptr) return {};
        vec<T> res;
        preorder_walk(root,res);
        return res;
    }
};

