class BinaryTree {
private:
	Node *root;
	void walkPreorder(Node *node);
	void walkInorder(Node *node);
public:
	BinaryTree(){ root = NULL; }
	void insert(int id);
	void find(int id);
	void walkPreorder();
	void walkInorder();
};

void BinaryTree::insert(int id)
{
	if (root == NULL) {
		root = new Node(id);
		return;
	}

	Node *node = root;
	while (1) {
		if (id < node->getId()) {
			if (node->getChildl() == NULL) {
				node->setChildl(new Node(id));
				break;
			}
			else {
				node = node->getChildl();
			}
		}
		else if (id > node->getId()) {
			if (node->getChildr() == NULL) {
				node->setChildr(new Node(id));
				break;
			}
			else {
				node = node->getChildr();
			}
		}
	}
}

void BinaryTree::find(int id)
{
	Node *node = root;
	while (node != NULL) {
		if (id == node->getId()) {
			cout << "yes" << endl;
			return;
		}
		else if (id < node->getId()) {
			node = node->getChildl();
		}
		else {
			node = node->getChildr();
		}
	}
	cout << "no" <<endl;
}

void BinaryTree::walkPreorder()
{
	walkPreorder(root);
	cout << endl;
}

void BinaryTree::walkPreorder(Node *node)
{
	if (node == NULL) return;
	cout << " " << node->getId();
	walkPreorder(node->getChildl());
	walkPreorder(node->getChildr());
}

void BinaryTree::walkInorder()
{
	walkInorder(root);
	cout << endl;
}

void BinaryTree::walkInorder(Node *node)
{
	if (node == NULL) return;
	walkInorder(node->getChildl());
	cout << " " << node->getId();
	walkInorder(node->getChildr());
}

