class Tree
{
public:
	Tree() {};
	~Tree() {};
	void Delete(Node* NODE)
	{
		if (NODE->right == 0 && NODE->left == 0) { delete NODE; }
		else
		{
			if (NODE->right != 0)
			{
				Delete(NODE->right);
			}
			if (NODE->left != 0)
			{
				Delete(NODE->left);
			}
			delete NODE;
		}
	}
	Node* CreateNode(int KEY, Node* PARENT) 
	{ 	
		Node* temp= new Node(KEY, PARENT);
		return temp;
	}
	void Insert(int KEY, Node* NODE)
	{
		if (NODE->key < KEY)
		{
			if (NODE->right == 0)
			{
				Node* temp=CreateNode(KEY, NODE);
				NODE->right = temp;
				temp->parent = NODE;
			}
			else Insert(KEY, NODE->right);
		}
		else
		{
			if (NODE->left == 0)
			{
				Node* temp = CreateNode(KEY, NODE);
				NODE->left = temp;
				temp->parent = NODE;
			}
			else Insert(KEY, NODE->left);
		}
	}
	bool Find(int KEY, Node* NODE)
	{
		if (NODE->key == KEY)return true;
		if (NODE->key < KEY)
		{
			if (NODE->right != 0)
			{
				return Find(KEY, NODE->right);
			}
			else return false;
		}
		else
		{
			if (NODE->left != 0)
			{
				return Find(KEY, NODE->left);
			}
