        return key;
    }

    shared_ptr<Node> Left(){
        return left;
    }

    shared_ptr<Node> Right(){
        return right;
    }

    //----Setter----
    void SetParent( shared_ptr<Node> p ){
        parent = p;
    }

    void SetLeft( shared_ptr<Node> l ){
        left = l;
    }

    void SetRight( shared_ptr<Node> r ){
        right = r;
    }

private:
    int key;
    shared_ptr<Node> parent;
    shared_ptr<Node> left;
    shared_ptr<Node> right;
};

void Find( shared_ptr<Node>& root, int key ){
    shared_ptr<Node> node( root );
    while( node ){
        if( node->Key() == key ){
            std::cout << "yes\n";
            return;
        }else if( node->Key() < key ){
            node = node->Right();
        }else{
            node = node->Left();
        }
    }
    std::cout << "no\n";
}

void Insert( shared_ptr<Node>& root, shared_ptr<Node>& z ){
    if( root->Key() == nullNum ){
        root.reset();
        root = std::move( z );
    }else{
        shared_ptr<Node> y = nullptr;
        shared_ptr<Node> x = root;
        while( x ){
            y = x;
            if( z->Key() < x->Key() ){
                x = x->Left();
            }else{
                x = x->Right();
            }
        }

        z->SetParent( y );

        if( z->Key() < y->Key() ){
            y->SetLeft( z );
        }else{
            y->SetRight( z );
        }
    }
}

void InorderTreeWalk( shared_ptr<Node> root ){
    if( root ){
        InorderTreeWalk( root->Left() );
        std::cout << " " << root->Key();
        InorderTreeWalk( root->Right() );
    }
}

void PreorderTreeWalk( shared_ptr<Node> root ){
    if( root ){
        std::cout << " " << root->Key();
        PreorderTreeWalk( root->Left() );
        PreorderTreeWalk( root->Right() );
    }
}

