void BinaryTree::insert(int key){
  Node *y = nil;
  Node *x = root;
  Node *z = new Node;
  // Node *z;
  // z = (Node *)malloc(sizeof(Node));
  z->key = key;
  z->left = nil;
  z->right = nil;

  while(x != nil){
    y = x;
    if(key > x->key){
      x = x->right;
    }
    else{
      x = x->left;
    }
  }
  z->parent = y;
  if(y == nil) root = z;
  else{
    if(key > y->key) y->right = z;
    else y->left = z;
  }
}

Node * BinaryTree::find(int key){
  Node *u = root;
  while(u != nil && u->key != key){
    if(key < u->key) u = u->left;
    else u = u->right;
  }
  return u;
}

void BinaryTree::Preorder(Node *x){
  if(x == nil) return;
  cout << " " << x->key;
  Preorder(x->left);
  Preorder(x->right);
}

void BinaryTree::Inorder(Node *x){
  if(x == nil) return;
  Inorder(x->left);
  cout << " " << x->key;
  Inorder(x->right);
}

void BinaryTree::Postorder(Node *x){
  if(x == nil) return;
  Postorder(x->left);
  Postorder(x->right);
  cout << " " << x->key;
}

