	}
	else if (p->key > key) {
	    parent = p;
	    p = p->left;
	}
	else {
	    return;
	}
    }

    node->parent = parent;

    if (parent->key < key) {
	parent->right = node;
    }
    else if (parent->key > key) {
	parent->left = node;
    }

