template <class T>
using sp = std::shared_ptr<T>;

struct Node
{
    explicit Node(int key)
        : key {key}
    {}

    int key;
    sp<Node> paprent {nullptr};
    sp<Node> left {nullptr};
    sp<Node> right {nullptr};
};

class BinarySearchTree
{
public:

    void insert(int key)
    {
        auto z = std::make_shared<Node>(key);
        //xの親を保持
        sp<Node> y {nullptr};
        auto x {root};

        while (x != nullptr)
        {
            //親を保持
            y = x;
            if (key < x->key)
                x = x->left;
            else
                x = x->right;
        }
        z->paprent = y;

        if (y == nullptr)           root = z;
        else if (z->key < y->key)   y->left = z;
        else                        y->right = z;
    }

    bool find(int key)
    {
        return find(key, root);
    }

    void printInorder()
    {
        printInorder(root);
    }

    void printPreorder()
    {
        printPreorder(root);
    }

private:

    sp<Node> root {nullptr};

    bool find(int key, sp<Node> n)
    {
        if (n == nullptr)
            return false;
        if (key == n->key)
            return true;
        else if (key < n->key)
            return find(key, n->left);
        else
            return find(key, n->right);
    }

    void printInorder(sp<Node> c)
    {
        if (c == nullptr)
            return;

        printInorder(c->left);
        std::cout << " " << c->key;
        printInorder(c->right);
    }

    void printPreorder(sp<Node> c)
    {
        if (c == nullptr)
            return;

        std::cout << " " << c->key;
        printPreorder(c->left);
        printPreorder(c->right);
    }
};

