struct Tree {
  int key;
  Tree *left, *right, *parent;
};

bool find(Tree* trees, int key) {
  if (trees == nullptr) return false;
  if (trees->key == key) return true;
  else if (key < trees->key) return find(trees->left, key);
  else return find(trees->right, key);
}

void insert(Tree* trees, Tree* new_tree) {
  Tree *cur_tree = trees;
  Tree *pre_tree;
  bool is_left_selected;
  while (cur_tree != nullptr) {
    pre_tree = cur_tree;
      if (new_tree->key < cur_tree->key) {
        cur_tree = pre_tree->left;
        is_left_selected = true;
      } else {
        cur_tree = pre_tree->right;
        is_left_selected = false;
      }
  }
  new_tree->parent = pre_tree;
  if (is_left_selected) {
    pre_tree->left = new_tree;
  } else {
    pre_tree->right = new_tree;
  }
}

