}

void postorder(Node* v) {
  if (v == NIL) return;
  postorder(v->left);
  postorder(v->right);
  printf(" %d", v->key);
}

void insert(Node* &T, Node *z) {
  Node *y = NIL;
  Node *x = T;
  while (x != NIL) {
    y = x;
    if (z->key < x->key)
      x = x->left;
    else
      x = x->right;
  }
  z->parent = y;

  if (y == NIL)
    T = z;
  else if (z->key < y->key)
    y->left = z;
  else
    y->right = z;
}

void find(Node* &T, int key){
  bool flag=false;
  Node *x = T;
  while(x!=NIL){
    if(x->key == key){
      flag = true;
      break;

    }else{
      if(x->key < key){
	x = x->right;
      }
      if(x->key > key){
	x = x->left;
      }
    }
  }

  if(flag){
    printf("yes\n");
  }else{
    printf("no\n");
  }
}



