using namespace std;

struct Node
{
  int value;
  Node *left, *right;
};

Node *root = NULL;

void insert(int key)
{
  Node *x = root;
  Node *y = NULL;
  Node *in = new Node;
  in->value = key;
  in->left = in->right = NULL;
  while (x != NULL)
  {
    y = x;
    if (x->value > key)
    {
      x = x->left;
    }
    else if (x->value < key)
    {
      x = x->right;
    }
  }

  if (y == NULL) root = in;
  else
  {
    if (y->value > key) y->left = in;
    else if (y->value < key) y->right = in;
  }
}

bool search(int key)
{
  Node *p = root;
  while (p != NULL)
  {
    if (p->value == key)
    {
      return true;
    }
    else if (p->value > key)
    {
