	void insert(int key) {
		NodePtr z = new Node(key, NULL, NULL, NULL);
		NodePtr y = NULL;
		NodePtr x = root;
		while (x != NULL) {
			y = x;
			if (z->key < x->key)
				x = x->left;
			else
				x = x->right;
		}
		z->parent = y;

		if (y == NULL)
			root = z;
		else {
			if (z->key < y->key)
				y->left = z;
			else
				y->right = z;
		}
	}

	bool find(int key) {
		NodePtr cur = root;
		while (cur != NULL) {
			if (key == cur->key)
