	}
};

Node* insert(Node *pRoot,Node *z) {
	Node *y = NULL;
	Node *x = pRoot;

	while (x != NULL) {
		y = x;
		if (z->key < x->key) {
			x = x->left;
		}
		else {
			x = x->right;
		}
	}

	if (y == NULL) {
		pRoot = z;
	}
	else if (z->key < y->key) {
		y->left = z;
	}
	else {
		y->right = z;
	}

	return pRoot;
}

