	cout << " " << pCur->key;
	printPreOrder(pCur->left);
	printPreOrder(pCur->right);
}

void freeTree(Node *p) {

	if (p == NULL) {
		return;
	}
	if (p->left != NULL) {
		p = p->left;
	}
	if (p->right != NULL) {
		p = p->right;
	}

	delete p;
	p = NULL;
}

bool findKey(Node *pCur, int key) {

	while (pCur != NULL) {
		if (key < pCur->key) {
			pCur = pCur->left;
		}
		else if (key > pCur->key) {
			pCur = pCur->right;
		}
		else {
			return true;
		}
	}
	return false;
}

