  buf=new branch(z,y);
  if(y==NULL)tree=buf;
  else if(buf->key<y->key)y->left=buf;
  else y->right=buf;
}
int search(int key,branch *p)
{
  if(p==NULL)return 0;
  if(p->key==key)return 1;
  if(key<p->key)
    {
      return search(key,p->left);
    }
  else
    {
      return search(key,p->right);
    }
  return 0;
}
