struct Node {
    int key;
    Node *parent;
    Node *left;
    Node *right;
};

class BinarySearchTree {
private:
    Node *root = nullptr;
public:
    BinarySearchTree() {}

    BinarySearchTree(int key)
    {
        insert(key);
    }

    void insert(int key)
    {
        /* Nodeの準備 */
        Node *node = new Node;
        node->key = key;
        node->left = nullptr;
        node->right = nullptr;

        /* 根がNULL(木が空)の場合 */
        if (root == nullptr)
        {
            node->parent = nullptr;
            root = node;
            return;
        }

        Node *parent = root;
        while (true)
        {
            if (node->key <= parent->key)
            {
                if (parent->left == nullptr)
                {
                    parent->left = node;
                    node->parent = parent;
                    break;
                } else
                    parent = parent->left;
            } else
            {
                if (parent->right == nullptr)
                {
                    parent->right = node;
                    node->parent = parent;
                    break;
                } else
                    parent = parent->right;
            }
        }
    }

    Node *find(int key)
    {
        Node *current = root;
        while(current != nullptr && current->key != key)
        {
            if(key < current->key)
                current = current->left;
            else
                current = current->right;
        }
        return current;
    }

    void inParse(Node *node)
    {
        if (node != nullptr)
        {
            inParse(node->left);
            cout << " " << node->key;
            inParse(node->right);
        }
    }

    void preParse(Node *node)
    {
        if (node != nullptr)
        {
            cout << " " << node->key;
            preParse(node->left);
            preParse(node->right);
        }
    }

    void print()
    {
        inParse(root);
        cout << endl;
        preParse(root);
        cout << endl;
    }
};

