typedef struct node{
  long long key;
  struct node* left;
  struct node* right;
} Node;

const int max_buffer = 32;

Node* createdNode(long long key){
  Node *new_node;
  new_node = (Node*)(calloc(1,sizeof(Node)));

  new_node->key = key;
  new_node->left = NULL;
  new_node->right = NULL;

  return new_node;
}

Node* insert(Node *T,Node *z){

  Node* current_node = T;

  if(current_node == NULL){
    T = z;
  }
  else{
    while(1){
      if(z->key < current_node->key){
	if(current_node->left != NULL) {
	  current_node = current_node->left;
	}
	else {
	  current_node->left = z;
	  break;
	}
      }
      else {
	if(current_node->right != NULL) {
	  current_node = current_node->right;
	}
	else {
	  current_node->right = z;
	  break;
	}
      }
    }
  }
  return T;
}

bool find(Node *node,long long key){
  if(node == NULL) return false;

  if(node->key == key) return true;
  else {
    if(key < node->key){
      return find(node->left,key);
    }else {
      return find(node->right,key);
    }
  }
}

void print_inorder(Node *node){

  if(node->left != NULL) print_inorder(node->left);

  printf(" %lld",node->key);

  if(node->right != NULL) print_inorder(node->right);
}

void print_preorder(Node *node){


  printf(" %lld",node->key);

  if(node->left != NULL) print_preorder(node->left);
  if(node->right != NULL) print_preorder(node->right);

  return;
}

