        }

void BinaryTree::insert(int newKey)
{
        node **p, *newNode;

        for (p = &root; *p != nullptr;) {
                if (newKey == (*p)->key) {
                        return;
                }
                p = (newKey < (*p)->key) ? &(*p)->left : &(*p)->right;
        }
        newNode = new node();
        newNode->key = newKey;
        *p = newNode;
}

