    node->parent = NULL;
    node->left = NULL;
    node->right = NULL;
    return node;
}

// ノードが属する木の根を再帰的に求める
Node* root(Node* node) {
    if (!node->parent) return node;
    else return root(node->parent);
}

// 木にノードを挿入する
void insert(Node* tree, int key) {
    Node* now = root(tree);  // 木の根
    Node* par = NULL;        // nowの親
    Node* z = new_node(key); // 挿入するノード

    // 根から下へ辿り挿入する場所を求める
    while (now) {
        par = now;
        if (z->key < now->key) {
            now = now->left;
        } else {
            now = now->right;
        }
    }
    z->parent = par;

    if (!par) {
        tree = z;
    } else if (key < par->key) {
        par->left = z;
    } else {
        par->right = z;
    }
}

