class TreeNode {
public:
    TreeNode *left;
    TreeNode *right;
    int val;
    TreeNode(int val) : left(nullptr), right(nullptr), val(val) {}
};

TreeNode* insert(TreeNode* root, int val)
{
    if (!root) return new TreeNode(val);
    TreeNode* curr = root;
    TreeNode* prev = nullptr;
    while (curr) {
        prev = curr;
        if (val < curr->val) {
            curr = curr->left;
        } else {
            curr = curr->right;
        }
    }
    if (val < prev->val)
        prev->left = new TreeNode(val);
    else
        prev->right = new  TreeNode(val);
    return root;
}

bool find(TreeNode* root, int val)
{
    if (!root) return false;

    TreeNode* curr = root;
    while (curr) {
        if (val < curr->val) {
            curr = curr->left;
        } else if (val > curr->val) {
            curr = curr->right;
        } else {
            return true;
        }
    }
    return false;
}

