               y->right = make_shared<Node>(y,nullptr,nullptr,val);
            }
        }
        ++size;
    }

    bool find(int val){
        if(size == 0) return false;
        shared_ptr<Node> x = root;
        while(x != nullptr){
            if(x->key == val){
                return true;
            }
            if(val < x->key){
                x = x->left;
            } else {
                x = x->right;
            }
        }
        return false;
    }

    void print(){
        if(size == 0) return;
        inorder(root);
        cout << endl;
        preorder(root);
        cout << endl;
    }

