        }
        else {
            x = nodes[x].right;
        }
    }
    nodes[n].parent = y;
    if (y == -1) {
        root = n;
    }
    else if (nodes[n].key < nodes[y].key) {
        nodes[y].left = n;
    }
    else {
        nodes[y].right = n;
    }
    return root;
}

