template<class T>
class BinarySearchTree {
public:
	class Node {
	public:
		Node *parent;
		Node *left;
		Node *right;
		T key;

		Node() : parent(nullptr), left(nullptr), right(nullptr) {}
	};

	Node* root;

	BinarySearchTree() : root(nullptr) {}

	void insert(T key) {
		Node *parent = root;
		Node *node = new Node;

		node->key = key;
		while (parent != nullptr) {
			node->parent = parent;
			if (node->key < parent->key)
				parent = parent->left;
			else
				parent = parent->right;
		}

		if (parent == root) {
			root = node;
		}
		else {
			if (node->key < node->parent->key)
				node->parent->left = node;
			else
				node->parent->right = node;
		}
	}

	bool find(T key) {
		Node *node = root;
		while (node != nullptr) {
			if (node->key == key)
				return true;
			else if (key < node->key)
				node = node->left;
			else
				node = node->right;
		}
		return false;
	}

	vector<T> getPreOrder() {
		vector<T> dst;
		calcPreOrder(dst, root);
		return dst;
	}

	void calcPreOrder(vector<T>& order, Node *node) {
		if (node == nullptr)
			return;
		order.push_back(node->key);
		calcPreOrder(order, node->left);
		calcPreOrder(order, node->right);
	}

	vector<T> getInOrder() {
		vector<T> dst;
		calcInOrder(dst, root);
		return dst;
	}

	void calcInOrder(vector<T>& order, Node *node) {
		if (node == nullptr)
			return;
		calcInOrder(order, node->left);
		order.push_back(node->key);
		calcInOrder(order, node->right);
	}

	vector<T> getPostOrder() {
		vector<T> dst;
		calcPostOrder(dst, root);
		return dst;
	}

	void calcPostOrder(vector<T>& order, Node *node) {
		if (node == nullptr)
			return;
		calcPostOrder(order, node->left);
		calcPostOrder(order, node->right);
		order.push_back(node->key);
	}
};

