#include <bits/stdc++.h>

template <typename T>
class BinarySearchTree {

  struct Node {
    T key;
    Node *par, *lhs, *rhs;
    Node(T k, Node *p, Node *l = 0, Node *r = 0) : key(k), par(p), lhs(l), rhs(r) {}
  };

  Node *root;

  // 入力：現在のノード curr, 中間順巡回のノードの順番を保存した配列 order
  // 出力：なし
  void inorder_dfs(Node *curr, std::vector<int> &order) {
    if (!curr) return;
    inorder_dfs(curr->lhs, order);
    order.push_back(curr->key);
    inorder_dfs(curr->rhs, order);
  }

  // 入力：現在のノード curr, 中間順巡回のノードの順番を保存した配列 order
  // 出力：なし
  void preorder_dfs(Node *curr, std::vector<int> &order) {
    if (!curr) return;
    order.push_back(curr->key);
    preorder_dfs(curr->lhs, order);
    preorder_dfs(curr->rhs, order);
  }

public:

  BinarySearchTree() : root(0) {}

  // 入力：なし
  // 出力：中間順巡回のノードの順番を保存した配列
  std::vector<int> inorder() {
    std::vector<int> res;
    inorder_dfs(root, res);
    return res;
  }

  // 入力：なし
  // 出力：先行順巡回のノードの順番を保存した配列
  std::vector<int> preorder() {
    std::vector<int> res;
    preorder_dfs(root, res);
    return res;
  }

  // 入力：値 x
  // 出力：なし
  void insert(const T &x) {
    Node *curr = root, *prev = 0;
    while (curr) {
      prev = curr;
      if (curr->key > x) curr = curr->lhs;
      else if (curr->key < x) curr = curr->rhs;
      else return;
    }
    (!prev ? root : (prev->key > x) ? prev->lhs : prev->rhs) = new Node(x, prev);
  }

  // 入力：値 x
  // 出力：キーに x を持つノードのポインタ (存在しない場合は 0)
  Node *find(const T &x) {
    Node *curr = root;
    while (curr) {
      if (curr->key == x) return curr;
      curr = (curr->key > x ? curr->lhs : curr->rhs);
    }
    return 0;
  }

};

