struct bst
{
	struct node { int v, l = -1, r = -1; };
	int root = -1, i = 0;
	vector<node> nodes;

	bst(int n)
	{
		nodes.resize(n);
	}

	int insert (int r, int v)
	{
		if (r == -1) {
			nodes[i].v = v;
			return i++;
		}
		node &n = nodes[r];
		if (n.v < v)
			n.r = insert(n.r, v);
		else
			n.l = insert(n.l, v);
		return r;
	}
	void insert (int n)
	{
		root = insert(root, n);
	}
	bool find(int r, int v)
	{
		if (r == -1)
			return false;
		node &n = nodes[r];
		return n.v == v ? true : n.v < v ? find(n.r, v) : find(n.l, v);
	}
	bool find (int n)
	{
		return find(root, n);
	}
	void print(int r, v &buf)
	{
		if (r == -1)
			return;
		node n = nodes[r];
		buf.push_back(n.v);
