/* intuitive version */
void binarySearchTreeInsert(Node** rootAddr, int val) {
    Node *newNode, *parent;

    newNode = (Node *) calloc(sizeof(Node), 1);
    newNode->parent = newNode->left = newNode->right = nullptr;
    newNode->key = val;

    parent = *rootAddr;

    while (true) {
        if (parent != nullptr) {
            if (parent->key > val) {
                if (parent->left != nullptr) {
                    parent = parent->left;
                } else {
                    break;
                }
            } else {
                if (parent->right != nullptr) {
                    parent = parent->right;
                } else {
                    break;
                }
            }
        } else {
            break;
        }
    }

    newNode->parent = parent;
    if (parent != nullptr) {
        if (parent->key > val) {
            parent->left = newNode;
        } else {
            parent->right = newNode;
        }
    } else {
        *rootAddr = newNode;
    }
}

bool binarySearchTreeSearch(Node* root, int val, int mode) {
    if (mode == 0) {
        // recursion
        return binarySearchTreeSearchRecursively(root, val);
    } else if (mode == 1) {
        // loop
        return binarySearchTreeSearchLoop(root, val);
    } else {
        return false;
    }
}

bool binarySearchTreeSearchRecursively(Node* root, int val) {
    if (root == nullptr) {
        return false;
    }

    if (root->key == val) {
        return true;
    } else if (root->key > val) {
        return binarySearchTreeSearchRecursively(root->left, val);
    } else {
        return binarySearchTreeSearchRecursively(root->right, val);
    }
}

bool binarySearchTreeSearchLoop(Node* root, int val) {
    while (root != nullptr) {
        if (root->key == val) {
            return true;
        } else if (root->key > val) {
            root = root->left;
        } else {
            root = root->right;
        }
    }
    return false;
}

/* mode: 0 - preorder; 1 - inorder; 2 - postorder */
void treeWalk(int** arrAddr, Node* root, int mode) {
    if (root == nullptr) {
        return;
    }

    if (mode == 0) {
        // preorder
        *(*arrAddr)++ = root->key;
    }

    treeWalk(arrAddr, root->left, mode);

    if (mode == 1) {
        // inorder
        *(*arrAddr)++ = root->key;
    }

    treeWalk(arrAddr, root->right, mode);

    if (mode == 2) {
        // postorder
        *(*arrAddr)++ = root->key;
    }
}

void freeBinarySearchTree(Node* root) {
    if (root == nullptr) {
        return;
    }

    freeBinarySearchTree(root->left);
    freeBinarySearchTree(root->right);

    free(root);
    root = nullptr;
}

