void Tree::Insert(Node* z)
{
	Node* y{}, *x{ this->root };
	while (x != NULL)
	{
		y = x;
		if (z->key < x->key)
			x = x->left;
		else
			x = x->right;
	}
	z->parent = y;

	if (y == NULL)
		this->root = z;
	else if (z->key < y->key)
		y->left = z;
	else
		y->right = z;
	return;
}

