{
	Pre_rec(this->root);
	printf("\n");
	return;
}

void Tree::Pre_rec(Node* n)
{
	if (n)
	{
		printf(" %d", n->key);
		Pre_rec(n->left);
		Pre_rec(n->right);
	}
	return;
}

