	this->In();
	this->Pre();
}

void Tree::Find(int k)
{
	if (this->Find_rec(this->root, k))
		printf("yes\n");
	else
		printf("no\n");
}

bool Tree::Find_rec(Node* n, int k)
{
	if (!n)
		return false;
	else if (n->key == k)
		return true;
	else if (k < n->key)
		return Find_rec(n->left, k);
	else
		return Find_rec(n->right, k);
}

