void insert(Node (*&root), Node *n)
{

  assert(n != nullptr && "nullptr catched\n");

  if (root == nullptr)
  {
    root = n;
    return;
  }

  Node *parent = nullptr;
  Node *child = root;

  while (child != nullptr)
  {
    parent = child;

    if (n->key_ < child->key_)
      child = child->left_;
    else
      child = child->right_;
  }

  if (n->key_ < parent->key_)
  {
    parent->left_ = n;

    DPRINTF("left - parent->key_ %d  n->key_ %d\n",
        parent->key_, n->key_);
  }
  else
  {
    parent->right_ = n;

    DPRINTF("right - parent->key_ %d  n->key_ %d\n",
        parent->key_, n->key_);
  }

}


bool find_recursive(const Node *node, int key)
{
  if (node == nullptr)
    return false;

  if (node->key_ == key)
    return true;

  return find_recursive(node->left_, key) | find_recursive(node->right_, key);
}


void find(const Node *node, int key)
{
  if (find_recursive(node, key))
    cout << "yes" << endl;
  else
    cout << "no" << endl;
}


