			n = n->left;
		} else if (key > n->key) {
			n = n->right;
		}
	}

	Node *node = new Node(key);
	node->parent = p;
	if (!p) {
		root = node;
	} else if (key < p->key) {
		p->left = node;
	} else {
		p->right = node;
	}
}

bool bst_find(Node *tree, int key) {
	if (!tree) return false;

	if (tree->key == key) {
		return true;
	} else if (key < tree->key) {
		return bst_find(tree->left, key);
	} else {
		return bst_find(tree->right, key);
	}

	return false;
}

