void insert(node* *focus) {
	if (*focus == NIL) {
		node* buf = (node*)malloc(sizeof(node));
		buf->key = k;
		buf->left = NIL;
		buf->right = NIL;
		buf->parent = n_i;
		*focus = buf;
	}
	else if (k < (*focus)->key) {
		n_i = (*focus);
		insert(&((*focus)->left));
	}
	else {
		n_i = (*focus);
		insert(&((*focus)->right));
	}
}

void fnd(node *focus) {
	if (focus->key == k) {
		printf("yes\n");
	}
	else if (focus == NIL) printf("no\n");
	else {
		if (k < focus->key) fnd(focus->left);
		else fnd(focus->right);
	}
}

void fnd2(node *focus) {
	if (focus->key == k) {
		n_f = focus;
	}
	else if (focus == NIL) return;
	else {
		if (k < focus->key) fnd2(focus->left);
		else fnd2(focus->right);
	}
}

void insert2(node* *focus) {
	cout << "inserting focus = " << (*focus)->key << endl;
	if (*focus == NIL) {
		n_i2->parent = n_i;
		*focus = n_i2;
	}
	else if (n_i2->key < (*focus)->key) {
		n_i = (*focus);
		insert2(&((*focus)->left));
	}
	else {
		n_i = (*focus);
		insert2(&((*focus)->right));
	}
}

void del() {
	fnd2(root);
	if (n_f->left == NIL&&n_f->right == NIL) {
		if (n_f == root) root = NIL;
		else {
			if (n_f->key < n_f->parent->key) n_f->parent->left = NIL;
			else n_f->parent->right = NIL;
		}
	}
	else {
		if (n_f == root) {
			if (n_f->left != NIL) {
				root = n_f->left;
				if (n_f->right != NIL) {
					n_i2 = n_f->right;
					insert2(&root);
				}
			}
			else {
				root = n_f->right;
			}
			root->parent = NIL;
		}
		else {
			if (n_f->key < n_f->parent->key) {
				if (n_f->left != NIL) {
					n_f->parent->left = n_f->left;
					n_f->parent->left->parent = n_f->parent;
				}
				if (n_f->right != NIL) {
					n_i2 = n_f->right;
					n_f->parent->right = NIL;
					insert2(&root);
				}
			}
			else {
				if (n_f->right != NIL) {
					n_f->parent->right = n_f->right;
					n_f->parent->right->parent = n_f->parent;
				}
				if (n_f->left != NIL) {
					n_i2 = n_f->left;
					n_f->parent->left = NIL;
					insert2(&root);
				}
			}
		}
	}
	if (n_f != NIL) free(n_f);
}

