template <typename T>
class BinaryTree{
  private:
    struct TreeNode{
      T value;
      TreeNode* left, *right, *parent;
    };

    struct Tree{
      TreeNode* root;
      TreeNode* nil;
    };

    Tree self;

    TreeNode* makeNode(T v, TreeNode* l, TreeNode* r, TreeNode* p){
      TreeNode* newNode = new TreeNode;
      newNode->left = l;
      newNode->right = r;
      newNode->parent = p;
      newNode->value = v;
      return newNode;
    }

  public: 
    BinaryTree(){
      self.nil = makeNode(0, nullptr, nullptr, nullptr);
      self.root = self.nil;
    } 

    TreeNode* newNode(T v){
      return makeNode(v, self.nil, self.nil, self.nil);
    }

    void insert(T value){
      TreeNode* z = newNode(value);
      TreeNode* y = self.nil;
      TreeNode* x = self.root;
      while ( x != self.nil ){
        y = x;
        if ( z->value < x->value )
          x = x->left;
        else
          x = x->right;
      }
      z->parent = y;


      if ( y == self.nil )
        self.root = z;
      else if ( z->value < y->value )
        y->left = z;
      else 
        y->right = z;
    }

    bool find(T value){
      return find(value, self.root);
    }

    bool find(T value, TreeNode* node){
      if (node == self.nil)
        return false;
      if (node->value == value) return true;
      if (value < node->value)
        return find(value, node->left);
      else
        return find(value, node->right);
    }

    void printInorder(TreeNode* root){
      if (root == self.nil) return;
      printInorder(root->left);
      printf(" %d", root->value);
      printInorder(root->right);
    }

    void printPreorder(TreeNode* root){
      if (root == self.nil) return;
      printf(" %d", root->value);
      printPreorder(root->left);
      printPreorder(root->right);
    }

    void print(void){
      printInorder(self.root);
      printf("\n");
      printPreorder(self.root);
      printf("\n");
    }
};

int main(){
