using namespace std;

enum class Walk
{
	ePreOrder = 0,
	eInOrder,
	ePostOrder
};


struct Node
{
	shared_ptr<Node>		parent;
	shared_ptr<Node>		left;
	shared_ptr<Node>		right;
	int						key;

	Node(int k)
	{
		key = k;
	}
};

shared_ptr<Node>			root;

void insert(int key)
{
	unique_ptr<Node>		z(new Node(key));
	weak_ptr<Node>			x = root;
	weak_ptr<Node>			y;

	while (x.use_count() != 0)
	{
		y = x;
		if (z->key < x.lock()->key)
		{
			x = x.lock()->left;
		}
		else
		{
			x = x.lock()->right;
		}
	}

	if (y.use_count() != 0)
	{
		z->parent = y.lock();
	}

	if (y.use_count() == 0)
	{
		root = move(z);
	}
	else
	{
		if (z->key < y.lock()->key)
		{
			y.lock()->left = move(z);
		}
		else
		{
			y.lock()->right = move(z);
		}
	}
}

void Order(weak_ptr<Node> nd, const Walk &wk)
{
	if (wk == Walk::ePreOrder)
		cout << " " << nd.lock()->key;
	if (nd.lock()->left.use_count() != 0)
		Order(nd.lock()->left, wk);
	if (wk == Walk::eInOrder)
		cout << " " << nd.lock()->key;
	if (nd.lock()->right.use_count() != 0)
		Order(nd.lock()->right, wk);
	if (wk == Walk::ePostOrder)
		cout << " " << nd.lock()->key;
}

bool	find(int key)
{
	weak_ptr<Node> nd = root;

	while (nd.use_count() != 0)
	{
		if (key == nd.lock()->key)
		{
			return true;
		}
		else if (key > nd.lock()->key)
		{
			nd = nd.lock()->right;
		}
		else
		{
			nd = nd.lock()->left;
		}
	}

	return false;
}

