        y = x;
        if(k < x->key) x = x->lef;
        else x = x->rig;
      }
      z->par = y;
      if(y == NIL) root = z;
      else if(z->key < y->key) y->lef = z;
      else y->rig = z;
    }

    bool finding(T k, Node *t){
      if(t == NIL) return false;
      if(t->key == k) return true;
      if(k < t->key) return finding(k,t->lef);
      else return finding(k,t->rig);
    }
