	return;
    }
    printf(" %d", node->key);
    firstPrint(node->left);
    firstPrint(node->right);
}

void middlePrint(Node *node) {
    if (node == nullptr) {
	return;
    }
    middlePrint(node->left);
    printf(" %d", node->key);
    middlePrint(node->right);
}

void insert(int key) {
    Node* node = (Node*)calloc(1, sizeof(Node));
    node->key = key;
    if (root == nullptr) {
	root = node;
	node->parent = nullptr;
	return;
    }

    Node* p = root;
    Node* parent=p->parent;
    while (p !=nullptr) {
	if (p->key < key) {
	    parent = p;
	    p = p->right;
	}
	else if (p->key > key) {
	    parent = p;
	    p = p->left;
	}
	else {
	    return;
	}
    }

    node->parent = parent;

    if (parent->key < key) {
	parent->right = node;
    }
    else if (parent->key > key) {
	parent->left = node;
    }

}

