    bool isFind = false;
    Node* p = root;
    while (p != nullptr) {
	if (p->key == key) {
	    isFind = true;
	    break;
	}
	else if (p->key > key) {
	    p = p->left;
	}
	else {
	    p = p->right;
	}
    }

    return isFind;

}

