struct Node {
    int key;
    Node* parent;
    Node* left;
    Node* right;
    Node(int k) : key(k) {}
};

void bintree_insert(Node*& root, int key)
{
    Node* node = new Node(key);
    if(!root) {
        root = node;
        return;
    }

    Node* parent = root;
    for(;;) {
        Node*& child = key < parent->key ? parent->left : parent->right;
        if(!child) {
            node->parent = parent;
            child = node;
            break;
        }
        parent = child;
    }
}

bool bintree_find(const Node* root, int key)
{
    const Node* node = root;
    for(;;) {
        if(!node) return false;

        if(node->key == key) return true;

        node = key < node->key ? node->left : node->right;
    }
}

void bintree_print_inorder(Node* node)
{
    if(!node) return;

    bintree_print_inorder(node->left);
    printf(" %d", node->key);
    bintree_print_inorder(node->right);
}

void bintree_print_preorder(Node* node)
{
    if(!node) return;

    printf(" %d", node->key);
    bintree_print_preorder(node->left);
    bintree_print_preorder(node->right);
}

void bintree_print(Node* root)
{
    bintree_print_inorder(root);
    puts("");

    bintree_print_preorder(root);
    puts("");
}

