        }
        else
        {
            y->r = z;
        }
    }

    bool find(int key)
    {
        Node* x = root;
        while (x)
        {
            if (x->key == key)
            {
                return true;
            }
            else if (key < x->key)
            {
                x = x->l;
            }
            else
            {
                x = x->r;
            }
        }
