};
void insert(Node *root, int key) {
  auto x = root;
  auto *parent = x->parent;

  while (x != nullptr) {
    parent = x;
    if (x->key > key) {
      x = x->left;
    } else {
      x = x->right;
    }
  }

  if (parent->key > key) {
    parent->left = new Node{key, parent, nullptr, nullptr};
  } else {
    parent->right = new Node{key, parent, nullptr, nullptr};
  }
}
bool find_bitree(Node *root, int key) {
  Node *parent = nullptr;
  auto x = root;

  while (x != nullptr) {
    parent = x;
    if (x->key == key) {
      return true;
    } else if (x->key > key) {
      x = x->left;
    } else {
      x = x->right;
    }
  }
  return false;
}
