struct Tree
{
	int key;
	Tree* parent, * left, * right;
};
Tree* root, * NIL;
int find(int key) {
	Tree* b = root;
	while (b != NIL)
	{
		if (b->key == key) return 1;
		else if (b->key > key) b = b->left;
		else
		{
			b = b->right;
		}
	}
	return 0;
}
void insert(Tree* k) {
	Tree* d = root;
	Tree* m = d;
	while (d != NIL)
	{
		m = d;
		if (k->key > d->key) {
			d = d->right;
		}
		else {
			d = d->left;
		}
	}
	k->parent = m;
	if (k->key > m->key) {
		m->right = k;
	}
	else {
		m->left = k;
	}
}
void midle(Tree* t) {
	if (t == NIL) return;
	midle(t->left);
	cout << " " << t->key;
	midle(t->right);
}
void pre(Tree* t) {
	if (t == NIL) return;
	cout << " " << t->key;
	pre(t->left);
	pre(t->right);
}
