        if (y->left==z) {
            y->left=x;
        } else if (y->right==z) {
            y->right=x;
        }
    } else {
        x = getSuccessor(z);
        if (x->parent==z) {
            if (y->left==z) y->left=x;
            else y->right=x;
            x->parent=y;
            x->left=z->left;
        } else {
            x->parent->left=x->right;
            x->right->parent=x->parent;
            if (z->parent->left==z) {
                z->parent->left=x;
            } else if (z->parent->right==z) {
                z->parent->right=x;
            }
            x->left=z->left;
            x->right=x->right;
        }
    }

    if (y==NIL) root=x;
    delete z;
}

