void insert(Node** T, int k)
{
    Node* n = *T;
    Node* parent = NULL;
    Node* new_node = new Node(k);

    while (n != NULL) {
        parent = n;
        if (new_node->key < n->key)
            n = n->left;
        else
            n = n->right;
    }
    new_node->parent = parent;

    if (parent == NULL)
        *T = new_node;
    else if (new_node->key < parent->key)
        parent->left = new_node;
    else
        parent->right = new_node;
}

bool find(Node* T, int k)
{
    Node* node = T;
    while (node != NULL) {
        if (node->key == k)
            return true;
        else if (node->key < k)
            node = node->right;
        else
            node = node->left;
    }
    return false;
}

