class Node {
public:
  int value;
  Node *parent;
  Node *left;
  Node *right;
  Node (int value) {
    this->value = value;
    this->parent = NULL;
    this->left = NULL;
    this->right = NULL;
  }
};

Node *insert(Node *root, Node *toInsert) {
  Node *parent = NULL;
  Node *current = root;
  while (current != NULL) {
    parent = current;
    if (toInsert->value < current->value)
      current = current->left;
    else
      current = current->right;
  }
  toInsert->parent = parent;
  if (parent == NULL) {
    root = toInsert;
  }
  else if (toInsert->value < parent->value)
    parent->left = toInsert;
  else
    parent->right = toInsert;
  return root;
}

void printInorder(Node *current) {
  if (current != NULL) {
    printInorder(current->left);
    cout << ' ' << current->value;
    printInorder(current->right);
  }
  return;
}

void printPreorder(Node *current) {
  if (current != NULL) {
    cout << ' ' << current->value;
    printPreorder(current->left);
    printPreorder(current->right);
  }
  return;
}

