  if (current == NULL) {
    cout << "no" << endl;
    return;
  }
  if (current->value == value) {
    cout << "yes" << endl;
    return;
  }
  if (value < current->value)
    find(current->left, value);
  else
    find(current->right, value);
  return;
}

