    while(subroot != nullptr) {
        if(subroot->value == v) {
            cout<<"yes"<<endl;
            return;
        }
        else if(subroot->value > v) subroot = subroot->left;
        else if(subroot->value < v) subroot = subroot->right;
    }
    cout<<"no"<<endl;
}

//メモリの開放
void Free(Node *a) {
    if(a->left != nullptr) Free(a->left);
    if(a->right != nullptr) Free(a->right);
    free(a);
}

//ノードを追加
void Insert(int x) {

    //追加するノードの作成
    Node *newNode = (Node *)malloc(sizeof(Node));
    newNode->value = x;

    //rootノード作成
    if(root == nullptr) {
        root = newNode;
        return;
    }

    Node *y;
    Node *subroot = root;
    while(subroot != nullptr) {
        y = subroot;
        if(subroot->value > x) subroot = subroot->left;
        else if(subroot->value < x) subroot = subroot->right;
    }

    newNode->parent = y;
    if(y->value > x) y->left = newNode;
    else if(y->value < x) y->right = newNode;
}

