    num = NIL;
    parent = NULL;
    left = NULL;
    right = NULL;
  }

  node(long long int n){
    num = n;
    parent = NULL;
    left = NULL;
    right = NULL;
  }

  void insert(long long int n){
    if(num==NIL) num=n;
    //値が小さいとき
    if(n<num){
      if(left==NULL){
        left = new node(n);
        left->parent=this;
      }else{
        left->insert(n);
      }

    //値が大きいか等しいとき
    }else if(n>num){
      if(right==NULL){
        right = new node(n);
        right->parent=this;
      }else{
        right->insert(n);
      }
    }else return;
  }

  void print_inorder(){
    if(left!=NULL) left->print_inorder();
    if(num!=NIL) cout << " " << num;
    if(right!=NULL) right->print_inorder();
  }

  void print_preorder(){
    if(num!=NIL) cout << " " << num;
    if(left!=NULL) left->print_preorder();
    if(right!=NULL) right->print_preorder();
  }

  bool find(long long int n){
    if(num==NIL) return false; //値が存在しないとき
    if(n<num){
      if(left==NULL) return false;
      else return left->find(n);
    }
    else if(n==num) return true;
    else if(n>num){
      if(right==NULL) return false;
      else return right->find(n);
    }
  }
};

