        if (root == 0) return;
        Node* cur = root;
        Node* prev = cur->parent;
        while(cur!=0){
            if (cur->parent == prev){
                if (cur->left != 0){
                    prev = cur;
                    cur = cur->left;
                    continue;
                } else {
                    prev = cur->left;
                }
            }
            if (prev == cur->left){
                cout << " " << cur->key;
                if (cur->right != 0){
                    prev = cur;
                    cur = cur->right;
                    continue;
                } else {
                    prev = cur->right;
                }
            }

            if (prev == cur->right){
                prev = cur;
                cur = cur->parent;
            }
        }
        cout << endl;
    }

