  ~Node() {
    if (right != NIL)
      delete right;
    if (left != NIL)
      delete left;
  }
};

Node *getRoot(Node *t) {
  Node *n = t;
  while (t->parent != NIL) {
    n = n->parent;
  }
  return n;
}

void insert(Node *t, Node *z) {
  Node *root = getRoot(t);
  Node *y = NIL;
  Node *x = root;
  while (x != NIL) {
    y = x;
    if (z->key < x->key)
      x = x->left;
    else
      x = x->right;
  }
  z->parent = y;

  if (y == NIL)
    root = z;
  else if (z->key < y->key)
    y->left = z;
  else
    y->right = z;
}

void printInorder(Node *t) {
  if (t != NIL) {
    printInorder(t->left);
    std::cout << " " << t->key;
    printInorder(t->right);
  }
}

