  }
}

bool find(Node *t, int k, bool found = false) {
  if (found)
    return true;
  if (t != NIL) {
    if (t->key == k)
      return true;
    if (t->key > k)
      return find(t->left, k, found);
    else
      return find(t->right, k, found);
  }
  return false;
}

