};

Node* root;

bool find(Node* node,int id){
    if(node->id==-1)
        return false;
    if(node->id==id)
        return true;
    if(node->id>id){
        if(node->l==nullptr)
            return false;
        return find(node->l,id);
    }else{
        if(node->r==nullptr)
            return false;
        return find(node->r,id);
    }
}

Node* dfs(Node* node,int id){
     // cout<<"dfs id:"<<node->id<<" nc:"<<node->nc<<endl;
     if(node->id==-1)
        return node;

     //cout<<"node-id:"<<node->id<<" id"<<id<<endl;
     if(node->id>id){
       if(node->l==nullptr){
            node->l = new Node();
            node->l->p = node;
     //      cout<<"node-p:"<<node->id<<endl;
            node->nc++;
            return node->l;
        }else{
            return dfs(node->l, id);
        }
      }else{
        if(node->r==nullptr){
           node->r = new Node();
           node->r->p = node;
           node->nc++;
           return node->r;
        }
        return dfs(node->r, id);
      }
}

