struct BSTNode {
	int key;
	BSTNode *lchild, *rchild, *parent;
	BSTNode(int k, BSTNode *p = nullptr, BSTNode *l = nullptr, BSTNode *r = nullptr) : key(k), lchild(l), rchild(r), parent(p)
	{}
};
typedef BSTNode* BSTree;

BSTree insert(BSTree& Root, int key)
{
	BSTree parent = nullptr;
	BSTree child = Root;
	while (child)
	{
		parent = child;
		if (key > child->key)
			child = child->rchild;
		else
			child = child->lchild;
	}
	child = new BSTNode(key, parent);
	if (!parent)
		Root = child;
	else if (parent->key > key)
		parent->lchild = child;
	else
		parent->rchild = child;
	return child;
}
void pre_order(BSTree T)
{
	if (!T)
		return;
	printf(" %d", T->key);
	pre_order(T->lchild);
	pre_order(T->rchild);
}
void in_order(BSTree T)
{
	if (!T)
		return;
	in_order(T->lchild);
	printf(" %d", T->key);
	in_order(T->rchild);
}

BSTree find(BSTree T, int key)
{
	while (T)
	{
		if (T->key > key)
			T = T->lchild;
		else if (T->key < key)
			T = T->rchild;
		else
			break;
	}
	return T;
}
