            {
                Node *q = new Node;
                q->val = x;
                q->left = q->right = NULL;
                if(root == NULL) root = q;
                return q;
            }
            else
            {
                if(x < p->val) p->left = insert(p->left, x);
                else p->right = insert(p->right, x);
                return p;
            }
        }
        bool find(Node *p, Type x)
        {
            if(p == NULL) return false;
            else if(x == p->val) return true;
            else if(x < p->val) return find(p->left, x);
            else return find(p->right, x);
        }
