	} else {
		y->right = z;
	}
}

bool find(Node *root, ll key) {
	if (root == nullptr) return false;
	if (root->key == key) return true;
	Node *ptr = key < root->key ? root->left : root->right;
	return find(ptr, key);
}

Node* find_using_loop(Node *root, ll key) {
	while (root != nullptr && key != root->key) {
		if (key < root->key) root = root->left;
		else root = root->right;
	}
	return root;
}

