        y = x;
        if (z->key < x->key) {
            x = x->left;
        }else {
            x = x->right;
        }
    }
    z -> parent = y;
    if (y == 0) {
        root = z;
    }else if (z->key < y->key) {
        y->left = z;
    }else {
        y->right = z;
    }
}

bool BinarySearchTree2::find(int n) {
    Node2 *p = root;
    while(p != 0) {
        if (p->key < n) {
            p = p->right;
        }else if (p->key == n) {
            return true;
        }else {
            p = p->left;
        }
    }
    return false;
}

