  Node *left = nullptr, *right = nullptr;

  void insert(int key);
  bool find(int key);
  void print_in();
  void print_pre();
};

void Node::insert(int key) {
  Node *&next = key < this->key ? left : right;
  if (next == nullptr) next = new Node{key};
  else next->insert(key);
}

bool Node::find(int key) {
  if (this->key == key) return true;
  Node *&next = key < this->key ? left : right;
  if (next == nullptr) return false;
  else return next->find(key);
}

void Node::print_in() {
