	void insert(int key)
	{
		if (root.key == 2000000001) {
			root.key = key;
			return;
		}

		Node* add = new Node;
		Node* parent = &root;

		add->key = key;
		add->left = NULL;
		add->right = NULL;

		while (parent != NULL) {
			add->parent = parent;
			if (add->key < parent->key) parent = parent->left;
			else parent = parent->right;
		}

		if (add->key < add->parent->key) add->parent->left = add;
		else add->parent->right = add;
	}
