		return;
	}
	printf(" %d", key[i]);
	printPreOrder(left[i]);
	printPreOrder(right[i]);
}

void insert(int k) {
	if (root == -1) {
		root = 0;
		key[root] = k;
		left[root] = -1;
		right[root] = -1;
		++numOfNodes;
		return;
	}

	int y;
	int x = root;
	while (x != -1) {
		y = x;
		if (k < key[x]) {
			x = left[x];
		}
		else {
			x = right[x];
		}
	}

	key[numOfNodes] = k;
	left[numOfNodes] = -1;
	left[numOfNodes] = -1;

	if (k < key[y]) {
		left[y] = numOfNodes++;
	}
	else {
		right[y] = numOfNodes++;
	}
}

void find(int k) {
	if (root == -1) {
		printf("no\n");
		return;
	}

	int x = root;
	while (x != -1) {
		if (k == key[x]) {
			printf("yes\n");
			return;
		}
		else if (k < key[x]) {
			x = left[x];
		}
		else {
			x = right[x];
		}
	}
	printf("no\n");
}

