Node* generate(ll key){
    Node *node=(Node *)malloc(sizeof(Node));
    node->key=key;
    node->left=NULL;
    node->right=NULL;
    node->p=NULL;
    return node;
}

Node* insert(Bst *bst,ll key){
    Node *node=generate(key);
    Node *cmp=bst->root;;
    while(cmp!=NULL){
        ll cmpkey=cmp->key;
        if(cmpkey<=key){
            if(cmp->right==NULL){
                cmp->right=node;
                node->p=cmp;
                break;
            }
            else cmp=cmp->right;
        }
        else {
            if(cmp->left==NULL){
                cmp->left=node;
                node->p=cmp;
                break;
            }
            else cmp=cmp->left;
        }
    }
    if(bst->size==0)bst->root=node;
    bst->size++;
    return node;
}

