template <typename T>
struct node_t {
  T key;
  node_t *lc, *rc;
  explicit node_t(T v): key(v), lc(nullptr), rc(nullptr) {}
};

template <typename T>
using tree_t = node_t<T> *;

template <typename T>
void insert(node_t<T> *&t, T v) {
  tree_t<T> z = new node_t<T>(v);
  tree_t<T> y = nullptr;
  tree_t<T> x = t;
  while (x) {
    y = x;
    if (z->key < x->key) {
      x = x->lc;
    } else {
      x = x->rc;
    }
  }
  if (!y) {
    t = z;
  } else if (z->key < y->key) {
    y->lc = z;
  } else {
    y->rc = z;
  }
}

template <typename T>
bool find(tree_t<T> t, T k) {
  if (!t) { return false; }
  if (t->key == k) { return true; }
  return (k < t->key)? find(t->lc, k) : find(t->rc, k);
}

template <typename T>
void inorder_walk(tree_t<T> t) {
  stack<tuple<tree_t<T>, bool>> stk;
  stk.emplace(t, false);
  while (!stk.empty()) {
    tree_t<T> ptr; bool op;
    tie(ptr, op) = stk.top(); stk.pop();
    if (!ptr) { continue; }
    if (op) {
      cout << " " << ptr->key;
    } else {
      stk.emplace(ptr->rc, false);
      stk.emplace(ptr, true);
      stk.emplace(ptr->lc, false);
    }
  }
  cout << endl;
}

template <typename T>
void preorder_walk(node_t<T> *t) {
  stack<tree_t<T>> stk;
  stk.push(t);
  while (!stk.empty()) {
    auto const ptr = stk.top(); stk.pop();
    if (!ptr) { continue; }
    cout << " " << ptr->key;
    stk.push(ptr->rc);
    stk.push(ptr->lc);
  }
  cout << endl;
}

