struct binary_search_tree {
    node* root = nullptr;
    int size = 0;
    binary_search_tree() {}
    void insert(int v) {
        size++;
        node* c = nullptr;  //子
        node* p = root;     //親
        while (p != nullptr) {
            c = p;
            if (v < (*p).value) {
                p = (*p).left;
            } else {
                p = (*p).right;
            }
        }
        if (c == nullptr) {
            root = new node(v);
        } else if (v < (*c).value) {
            (*c).left = new node(v);
            (*((*c).left)).parent = c;
        } else {
            (*c).right = new node(v);
            (*((*c).right)).parent = c;
        }
    }
    node* find(int v) {
        node* x = root;
        while (x != nullptr) {
            if (v < (*x).value) {
                x = (*x).left;
            } else if (v > (*x).value) {
                x = (*x).right;
            } else {
                return x;
            }
        }
        return nullptr;
    }
    void print_inorder(node* now) {
        if ((*now).left != nullptr) { print_inorder((*now).left); }
        std::cout << " " << (*now).value;
        if ((*now).right != nullptr) { print_inorder((*now).right); }
    }
    void print_preorder(node* now) {
        std::cout << " " << (*now).value;
        if ((*now).left != nullptr) { print_preorder((*now).left); }
        if ((*now).right != nullptr) { print_preorder((*now).right); }
    }
    void print() {
        print_inorder(root);
        std::cout << std::endl;
        print_preorder(root);
        std::cout << std::endl;
    }
    void del(node* now) {
        if ((*now).left != nullptr) { del((*now).left); }
        if ((*now).right != nullptr) { del((*now).right); }
        delete now;
    }
    ~binary_search_tree() { del(root); }
};

