class BinaryTree
{
private:
        struct Node {
                int key;
                Node *parent, *left, *right;
                Node () : parent(nullptr), left(nullptr), right(nullptr) {}
                Node (int key) : key(key), parent(nullptr), left(nullptr), right(nullptr) {}
        };
public:
        BinaryTree () : root(nullptr) {}
        void insert(int k)
        {
                Node *data;
                Node **pos = findInsertPos(k, &root);

                data = new Node(k);
                *pos = data;
                data->parent = *pos;
        }

        bool find(int k) { return ( find(k, root) ); }
        void preorder() { preorder(root); }
        void inorder() { inorder(root); }
private:
        Node *root;

        Node **findInsertPos(int k, Node **node)
        {
                if ( *node == nullptr ) return ( node );
                if ( k < (*node)->key ) return ( findInsertPos(k, &((*node)->left)) );
                else return ( findInsertPos(k, &((*node)->right)) );
        }

        bool find(int k, Node *node)
        {
                if ( node == nullptr ) return ( false );
                if ( node->key == k ) return ( true );
                if ( k < node->key ) return ( find(k, node->left) );
                else return ( find(k, node->right) );
        }

        void preorder(Node *node)
        {
                if ( node == nullptr ) return;
                cout << " " << node->key;
                preorder(node->left);
                preorder(node->right);
        }

        void inorder(Node *node)
        {
                if ( node == nullptr ) return;
                inorder(node->left);
                cout << " " << node->key;
                inorder(node->right);
        }
