  Node() : parent(NULL), left(NULL), right(NULL), value(-1) {
  }
};

Node* root = NULL;

void insert(int value) {
  if(root == NULL) {
    root = new Node();
    root->value = value;
    return;
  }

  Node* parent = root;
  Node* node = root;
  int left = 0;
  while(node != NULL) {
    parent = node;
    if(node->value < value) {
      left = 0;
      node = node->right;
    } else {
      left = 1;
      node = node->left;
    }
  }

  Node* newNode = new Node();
  newNode->value = value;
  newNode->parent = parent;
  if(left == 1) {
    parent->left = newNode;
  } else {
    parent->right = newNode;
  }
}

