    return x;
}

Node *treeMaximum(Node *x){
    while(x->right!=NIL)x=x->right;
    return x;
}

Node *treeSearch(Node *u, int k){
    while(u!=NIL && k!=u->key){
        if(k<u->key)u=u->left;
        else u=u->right;
    }
    return u;
}

Node *treeSuccessor(Node *x){
    if(x->right!=NIL)return treeMinimum(x->right);
    Node *y=x->parent;
    while(y!=NIL&&x==y->right){
        x=y;
        y=y->parent;
    }
    return y;
}

void treeDelete(Node *z){
  Node *y;
  Node *x;

  if(z->left==NIL||z->right==NIL)y=z;
  else y=treeSuccessor(z);

  if(y->left!=NIL){
      x=y->left;
  }else{
      x=y->right;
  }

  if(x!=NIL){
      x->parent=y->parent;
  }

  if(y->parent==NIL){
      root=x;
  }else{
      if(y==y->parent->left){
          y->parent->left=x;
      }else{
          y->parent->right=x;
      }
  }

  if(y!=z){
      z->key=y->key;
