{
	int Count = 0;
	std::cin >> Count;
	TNode* Root = new TNode();
	for(int i = 0; i < Count; ++i){
		std::string Command;
		std::cin >> Command;
		Execute(Command, Root);
	}
	Delete(Root);
	return 0;
}

