    // 根である自身を出力する
    cout << " " << node->key;
    // 左
    if(node->left != NIL){
        preOrder(node->left);
    }
    // 右
    if(node->right != NIL){
        preOrder(node->right);
    }
}

/**
    対象のキーを散策する
*/
bool find(int key){
    bool find = false;
    Node* x = root;
    while(x != NIL){
        if(x->key == key){
            find = true;
            break;
        }
        else if(key < x->key){
            x = x->left;
        }
        else{
            x = x->right;
        }
    }
    return find;
}

/**
 左部分木 → 根節点 → 右部分木の順番で節点をまわること
 */
void inOrder(Node* node){
    if(node == NIL){
        return;
    }
    // 左を探す
    if(node->left != NIL){
        inOrder(node->left);
    }
    // 左がなくなったら左を出力する
    cout << " " << node->key;
    // 右
    if(node->right != NIL){
        inOrder(node->right);
    }
}

