		if (pa.lock()->left.use_count() == 0)
		{
			pa.lock()->right = nd.lock()->left;
			pa.lock()->right->parent = pa.lock();
		}
		else
		{
			if (pa.lock()->left->key == nd.lock()->key)
			{
				pa.lock()->left = nd.lock()->left;
				pa.lock()->left->parent = pa.lock();
			}
			else
			{
				pa.lock()->right = nd.lock()->left;
