			}
		}
	}
	else
	{
		weak_ptr<Node>		pa;
		pa = nd.lock()->parent;

		weak_ptr<Node>		next = nd.lock()->right;
		bool	isNext = true;		//???

		while (next.lock()->left.use_count() != 0)
