		if (isNext)
		{
			if (pa.lock()->left.use_count() == 0)
			{
				pa.lock()->right = next.lock();
				pa.lock()->right->parent = pa.lock();
			}
			else
			{
				if (pa.lock()->left->key == nd.lock()->key)
				{
					pa.lock()->left = next.lock();
					pa.lock()->left->parent = pa.lock();
				}
				else
				{
					pa.lock()->right = next.lock();
					pa.lock()->right->parent = pa.lock();
				}
			}
			next.lock()->left = left.lock();
		}
		else
		{
			if (next.lock()->right.use_count() == 0)
			{
				if (pa.lock()->left.use_count() == 0)
				{
					pa.lock()->right = next.lock();
					pa.lock()->right->parent = pa.lock();
				}
				else
				{
					if (pa.lock()->left->key == nd.lock()->key)
					{
						pa.lock()->left = next.lock();
						pa.lock()->left->parent = pa.lock();
					}
					else
					{
						pa.lock()->right = next.lock();
						pa.lock()->right->parent = pa.lock();
					}
				}
				next.lock()->left = left.lock();
				next.lock()->right = right.lock();
				next.lock()->parent->left.reset();
			}
			else
			{
				weak_ptr<Node>		nextParent = next.lock()->parent;
				weak_ptr<Node>		nextChildRight = next.lock()->right;

				if (pa.lock()->left.use_count() == 0)
				{
