template<typename T>
class BinTree;

template<typename T>
class Node {
    T value;
    Node<T> *parent, *left, *right;
    Node (T _value) : value(_value) {
        parent = nullptr;
        left = nullptr;
        right = nullptr;
    }
    Node (){
        parent = nullptr;
        left = nullptr;
        right = nullptr;
    }
    friend BinTree<T>;
    public:
    void inorder(std::vector<T> &ret) {
        if(left) left->inorder(ret);
        ret.push_back(value);
        if(right) right->inorder(ret);
    }
    void preorder(std::vector<T> &ret) {
        ret.push_back(value);
        if(left) left->preorder(ret);
        if(right) right->preorder(ret);
    }
    void postorder(std::vector<T> &ret) {
        if(left) left->postorder(ret);
        if(right) right->postorder(ret);
        ret.push_back(value);
    }
};

template<typename T> 
class BinTree{
    Node<T> *root;
    size_t size;
    void insert_main(Node<T> *z) {
        Node<T> *y = nullptr, *x = root;
        while(x) {
            // std::cout << x << '\n';
            y = x;
            if(z->value < x->value) {
                x = x->left;
            }
            else {
                x = x->right;
            }
        }
        z->parent = y;
        if(y == nullptr) {
            root = z;
        }
        else if(z->value < y->value) {
            y->left = z;
        }
        else {
            y->right = z;
        }
    }
    bool find_main(T x) {
        Node<T> *y = root;
        while(y) {
            if(y->value == x) {
                return true;
            }
            if(x < y->value) {
                y = y->left;
            }
            else {
                y = y->right;
            }
        }
        return false;
    }
    public:
    BinTree() {
        root = nullptr;
        size = 0;
    }
    bool empty() {return size == 0;}
    void insert(T x) {
        Node<T> *z = new Node<T>(x);
        insert_main(z);
    }
    bool find(T x) {return find_main(x);}
    void preorder(std::vector<T> &ret) {root->preorder(ret);}
    void inorder(std::vector<T> &ret) {root->inorder(ret);}
    void postorder(std::vector<T> &ret) {root->postorder(ret);}
};

