class Node{
public:
	Node *parent;
	Node *l;
	Node *r;
	long key;

	Node() : parent(NULL), l(NULL), r(NULL), key(0){
		return;
	}
	~Node(){
		if(l != NULL){ delete l; l = NULL; }
		if(r != NULL){ delete r; r = NULL; }
	}
};

void insert(Node **root_handle, long key){
	Node *y = NULL;
	Node *x = *root_handle;

	while(x != NULL){
		y = x;
		if(key < x->key){
			x = x->l;
		}
		else{
			x = x->r;
		}
	}

	Node *z = new Node;
	z->parent = y;
	z->key = key;

	if(y == NULL){
		*root_handle = z;
	}
	else if(z->key < y->key){
		y->l = z;
	}
	else{
		y->r = z;
	}
	return;
}

bool find(Node *n, long key){
	if(n->key == key){
		return true;
	}

	if(key < n->key){
		if(n->l != NULL){
			return find(n->l, key);
		}
		else{
			return false;
		}
	}
	else{
		if(n->r != NULL){
			return find(n->r, key);
		}
		else{
			return false;
		}
	}
	return false;
}

void print_inorder(Node *n){
	if(n->l != NULL){
		print_inorder(n->l);
	}
	std::cout << " " << n->key;

	if(n->r != NULL){
		print_inorder(n->r);
	}
	return;
}

void print_preorder(Node *n){
	std::cout << " " << n->key;
	if(n->l != NULL){
		print_preorder(n->l);
	}

	if(n->r != NULL){
		print_preorder(n->r);
	}
	return;
}

