    node->right = NULL;
    node->left = NULL;
    return node;
}

void Insert(llong key){
    if(root==NULL){
        root = (NODE*)malloc(sizeof(NODE));
        root->left = NULL;
        root->right = NULL;
        root->key = key;
        return;
    }
    NODE *now = root;
    NODE *prev;
    NODE *new_node = MakeNode(key);
    while(now!=NULL){
        if(now->key >= key){
            prev = now;
            now  = now->left;
        }else{
            prev = now;
            now  = now->right;
        }
    }
    if(prev->key >= key){
        prev->left = new_node;
    }else{
        prev->right = new_node;
    }
}

