Node tree[500001];
int treesize;
int root = NIL;
int findlist[100000];

void in(int id)
{
	if (id == NIL) return;
	cout << " " << tree[id].key;
	in(tree[id].left);
	in(tree[id].right);
}

void pre(int id)
{
	if (id == NIL) return;
	pre(tree[id].left);
	cout << " " << tree[id].key;
	pre(tree[id].right);
}

bool find(int id)
{
	if (!treesize) return false;
	else
	{
		for(int i = 0; i < treesize;++i)
		{
			if (tree[i].key == id) return true;
		}
		return false;
	}
}

void insert(int key)
{
	int y = NIL;
	int x = root;
	while (x != NIL)
	{
		y = x;
		if (key < tree[x].key) x = tree[x].left;
		else x = tree[x].right;
	}
	tree[treesize].parent = y;

	if (y == NIL) root = treesize;
	else if (key < tree[y].key) tree[y].left = treesize;
	else tree[y].right = treesize;

	tree[treesize].left = NIL;
	tree[treesize].right = NIL;
	tree[treesize].key = key;

	treesize++;
}

