class Node{
//ノードはポインタでもっておこう
public:
  ///ノードの番号
  int num;
  //そのノードの親
  //rootの場合はnullptr
  Node* p=nullptr;
  //そのノードの子
  //葉でなければ少なくとも一つ持つ
  Node* l=nullptr;Node* r=nullptr;
};

//参照とかポインタとか気をつけよ(統一する)
//関数内はスタックに保存される
//xは根のNode
void insert(Node* &root,int k){
  //見ているNode、そのNodeの親を、それぞれx,yで管理する
  //newで確保するとポインタはスタック領域にあるので破棄されるけどnewで確保した領域はヒープ領域にあるから残ってる
  //つまり、その領域をvectorにあげれば良い
  Node* z= new Node;z->num=k;
  Node* y=nullptr;
  Node* x=root;

  while(x!=nullptr){
    y=x;
    if(z->num<x->num){
      x=x->l;
    }else{
      x=x->r;
    }
  }

  if(y==nullptr){
    root=z;
  }else{
    z->p=y;
    if(z->num<y->num){
      y->l=z;
    }else{
      y->r=z;
    }
  }
}

void pre_calc(Node* &n,vector<int>& v){
  if(n==nullptr) return;
  v.push_back(n->num);
  pre_calc(n->l,v);
  pre_calc(n->r,v);
}

void in_calc(Node* &n,vector<int>& v){
  if(n==nullptr) return;
  in_calc(n->l,v);
  v.push_back(n->num);
  in_calc(n->r,v);
}

void tree_print(Node* N){
  vector<int> vin;vector<int> vre;
  //v[0]はrootNode、vin,vreは出力したいものを入れておく
  in_calc(N,vin);
  pre_calc(N,vre);
  int le=vin.size();
  //printするところ
  for(int i=0;i<le;i++){
    cout << " " << vin[i];
  }
  cout << endl;
  for(int i=0;i<le;i++){
    cout << " " << vre[i];
  }
  cout << endl;
}

