      tree.insert(val);
    } else if (cmd == "find") {
      int val;
      cin >> val;
      ss << (tree.find(val) ? "yes" : "no") << endl;
    } else if (cmd == "print") {
      tree.print(ss);
    }
  }
  cout << ss.str();
}

