	}
	else
	{
		if(tree[now][0] > key)		//left
		{
			if(tree[now][1] == numeric_limits<int>::min())	//child none
			{
				tree[now][1] = count;
				tree[count][0] = key;
			}
			else											//child exist
			{
				insert(tree,key,tree[now][1]);
			}
		}
		else						//right
		{
