  S->parent = S->left = S->right = NULL;
  x = T;
  while(x != NULL){
    y = x;
    if(key < x->key) x = x->left;
    else x = x->right;
  }
  S->parent = y;
  if(S->key < y->key) y->left = S;
  else y->right = S;
}
