};

struct BinarySearchTree
{
    Node *root;
    BinarySearchTree()
    {
        root = NULL;
    }
    void insert(int z)
    {
        insert(new Node(z));
    }
    void insert(Node *z)
    {
        Node *y = NULL, *x = root;
        while (x != NULL)
        {
            y = x;
            if (z->key < x->key)
            {
                x = x->left;
            }
            else
            {
                x = x->right;
            }
        }
        z->par = y;

        if (y == NULL)
        {
            root = z;
        }
        else if (z->key < y->key)
        {
            y->left = z;
        }
        else
        {
            y->right = z;
        }
    }
    void preorder(Node *cur)
    {
        if (cur == NULL)
            return;
        cout << " " << cur->key;
        preorder(cur->left);
        preorder(cur->right);
    }
    void inorder(Node *cur)
    {
