        inorder(cur->left);
        cout << " " << cur->key;
        inorder(cur->right);
    }
    void print()
    {
        inorder(root);
        cout << endl;
        preorder(root);
        cout << endl;
    }
    bool find(int v)
    {
        bool f = false;
        Node *x = root;
        while (x != NULL)
        {
            if (x->key == v)
            {
                f = true;
                break;
            }
            if (v < x->key)
            {
                x = x->left;
            }
            else
            {
                x = x->right;
            }
        }
        return f;
    }
};

