      tree.print_inorder();
      tree.print_preorder();
    }
    else if (buf[0] == 'f') {
      fscanf(stdin, "%d", &key);
      if (tree.find(key)) { fprintf(stdout, "yes\n"); }
      else { fprintf(stdout, "no\n"); }
    }
  }
  return 0;
}

