struct Tree {
    Node *root;
};

void insert(Tree *T, int key) {
    Node *n = (Node *)malloc(sizeof(Node));
    n->key = key;
    n->parent = NIL;
    n->left = NIL;
    n->right = NIL;

    if (T->root == NIL) {
        T->root = n;
        return;
    }

    Node *x;
    x = T->root;
    bool continued = true;
    while (continued) {
        if (x->key >= key) {
            if (x->left != NIL) {
                x = x->left;
                continue;
            }

            n->parent = x;
            x->left = n;
            continued = false;
            return;
        }

        if (x->key <= key) {
            if (x->right != NIL) {
                x = x->right;
                continue;
            }

            n->parent = x;
            x->right = n;
            continued = false;
            return;
        }
    }
};

bool find(Node *N, int key) {
    Node *x;
    x = N;

    while(x != NIL && x->key != key) {
        if (key <= x->key) {
            x = x->left;
        } else {
            x = x->right;
        }
    }

    if (x == NIL) {
        return false;
    }

    return true;
}

