typedef struct node{
	int key=0;
	node *left=nullptr,*right=nullptr;
	node(){};
	node(int s):key(s){};
}node;

class BinarySearchTree{
private:
	node *root = new node;
	vector<int> inorder,preorder;
	int num_of_nodes=0;

	void getInsertPosition(node *now,int value){
		if(now->key>value){
			if(now->left==nullptr){
				node *tmp = new node;
				tmp->key=value;
				now->left=tmp;
			}else getInsertPosition(now->left, value);
		}else{
			if(now->right==nullptr){
				node *tmp = new node;
				tmp->key=value;
				now->right=tmp;
			}else getInsertPosition(now->right, value);
		}
	}
	void dfs(node *now){
		preorder.push_back(now->key);
		if(now->left!=nullptr)dfs(now->left);
		inorder.push_back(now->key);
		if(now->right!=nullptr)dfs(now->right);
		return;
	}
	void printVector(vector<int> a){
		for(auto x:a)cout<<" "<<x;
		cout<<endl;
	}
	bool containValue(node *now, int target){
		if(now->key==target)return true;
		if(now->left!=nullptr&&target<now->key)return containValue(now->left, target);
		if(now->right!=nullptr&&target>now->key)return containValue(now->right, target);
		return false;
	}
public:
	BinarySearchTree(){};
	void insert(int value){
		if(num_of_nodes==0){
			root->key=value;
			num_of_nodes++;
			return;
		}
		getInsertPosition(root, value);
	}

	void findValue(int value){
		cout<<(containValue(root,value)?"yes":"no")<<endl;
	}

	void solve(){
		inorder.clear(),preorder.clear();
		dfs(root);
		printVector(inorder);
		printVector(preorder);
	}
};


