typedef struct tree T;

void insert(T *t, int k)
{
    T *insert_node, *nownode;
    insert_node = (T *)malloc(sizeof(T));
    insert_node->node = k;
    insert_node->parent = NULL;
    insert_node->left = NULL;
    insert_node->right = NULL;
    if(t->left == NULL && t->right == NULL){
        t->left = insert_node;
    }
    else {
        insert_node->parent = t;
        nownode = t->left;
        bool isleft = true;
        while(nownode != NULL){
            insert_node->parent = nownode;
            if(nownode->node > k) {
                nownode = nownode->left;
                isleft = true;
            }else {
                nownode = nownode->right;
                isleft = false;
            }
        }
        if(isleft) (insert_node->parent)->left = insert_node;
        else (insert_node->parent)->right = insert_node;}
    return;
}

T* find(T *t, int k)
{
    if(t == NULL) return t;
    else if(t->node == -1) return find(t->left, k);
    else if(t->node == k) return t;
    else if(t->node < k) return find(t->right, k);
    else return find(t->left, k);
}

