  Node* cur = root;
  Node* pre = cur->parent;

  if(root == 0) return;

  while(cur){
   if(pre == cur->parent){
    if(order == PREORDER) cout << " " << cur->value;
    if(cur->left != 0){
     pre = cur;
     cur = cur->left;
     continue;
    }else{
     pre = cur->left;
