typedef struct Node {
    int id;
    struct Node *left;
    struct Node *right;
} Node;

Node *insert_iter(Node *t, Node *z){
    if(t == nullptr) return z;
    if(z->id <= t->id) t->left = insert_iter(t->left, z);
    else t->right = insert_iter(t->right, z);
    return t;
}

void insert(Node **root, Node *z){
    *root = insert_iter(*root, z);
}

bool search(Node *node, int id){
    if(node == nullptr) return false;
    else if(id < node->id) return search(node->left, id);
    else if(id > node->id) return search(node->right, id);
    return true;
}

void print_inorder(Node *node){
    if(node == nullptr) return;
    print_inorder(node->left);
    std::printf(" %d",node->id);
    print_inorder(node->right);
}

void print_preorder(Node *node){
    if(node == nullptr) return;
    std::printf(" %d", node->id);
    print_preorder(node->left);
    print_preorder(node->right);
}

void deleteNode(Node *node){
    if(node == nullptr) return;
    deleteNode(node->left);
    deleteNode(node->right);
    free(node);
}

