      ++size;
    } else if(s[0] == 'p') {
      psize = 0;
      qsort(0, size);
      for(j = 0; j < size; ++j) {
        printf(" %d", v[j].second);
      }
      printf("\n");
      for(j = 0; j < size; ++j) {
        printf(" %d", preorder[j].second);
      }
      printf("\n");
    } else {
      scanf("%d", &k);
      psize = 0;
      qsort(0, size);
      printf(binary_search(k)!=-1?"yes\n":"no\n");
    }
  }
  return 0;
}

