node * Delete(node *p,int x){

	if(p->key == x){

		if(p->left==NULL && p->right==NULL)/*葉*/
			return NULL;

		if(p->left==NULL || p->right==NULL){/*子1つ*/
			if(p->left!=NULL)
				return p->left;
			else
				return p->right;
		}

		node **q=&(p->right);
		while((*q)->left!=NULL)
			q=&((*q)->left);
		p->key=(*q)->key;
		(*q)=Delete((*q),(*q)->key);
		return p;

	}

	if(p->key > x)
		p->left=Delete(p->left,x);
	else
		p->right=Delete(p->right,x);

	return p;

}

