   戻り値  存在 TRUE  存在しない FALSE  */
int find(int k)
{
  Node x = root;

  /* Tが空の場合 */
  if( root == NIL )
    return FALSE;

  while( x != NIL )
    {
      /* keyの値がkのノードが存在した場合 */
      if( x->key == k )
	return TRUE;

      if( k < x->key )
	x = x->left;      /* 左の子に移動 */
      else
	x = x->right;     /* 右の子に移動 */

    }

  return FALSE;   /* 存在しなかった場合 */
}

