struct node {
  int key;
  struct node *parent;
  struct node *left;
  struct node *right;
};

struct node *tree = NULL;

void insert(struct node **root, struct node *node)
{
  struct node *parent = NULL;
  struct node *current = *root;

  while (current != NULL) {
    parent = current;
    if (node->key < current->key) {
      current = current->left;
    } else {
      current = current->right;
    }   
  }

  node->parent = parent;

  if (parent == NULL) {
    *root = node;
  } else if (node->key < parent->key) {
    parent->left = node;
  } else {
    parent->right = node;
  }
}

int find_tree(struct node* node, int key)
{
  if (node != NULL) {
    if (node->key > key) {
      return find_tree(node->left, key);
    } else if (node->key < key) {
      return find_tree(node->right, key);
    } else {
      return 1;
    }
  }
  return 0;
}

void preorder_traverse(struct node* node)
{
  if (node != NULL) {
    printf(" %d", node->key);
    preorder_traverse(node->left);
    preorder_traverse(node->right);
  }
}

void inorder_traverse(struct node *node)
{
  if (node != NULL) {
    inorder_traverse(node->left);
    printf(" %d", node->key);
    inorder_traverse(node->right);
  }
}

void tree_destroy(struct node* node)
{
  if (node != NULL) {
    tree_destroy(node->left);
    tree_destroy(node->right);
    free(node);
  }
}

