    } else if (cur->number == num) {
      return node;
    } else {
      node = &cur->right;
    }
  }
  return NULL;
}

struct node** findmin(struct node *node) {
  struct node** min = &node;
  while((*min)->left) {
    min = &(*min)->left;
  }
  return min;
}

void delete(int num) {
  struct node **node = find(num);
  if(node == NULL) return;
  struct node *cur = *node;
  if(!cur->left && !cur->right) {
    *node = NULL;
  } else if (cur->left && cur->right) {
    struct node** parent_min = findmin(cur->right);
    struct node* min = (*parent_min);
    min->left = cur->left;
    min->right = cur->right;
    (*parent_min) = NULL;
    (*node) = min;
  } else {
    (*node) = cur->left ? cur->left : cur->right;
  }
  free(cur);
}

