  if (n->k <= r->k) {
    if (r->l == NULL) {
      r->l = n;
      n->p = r;         
    } else {              
      insert_node(r->l, n);
    }           
  } else {      
    if (r->r == NULL) {     
      r->r = n;
      n->p = r;
    } else {   
      insert_node(r->r, n);
    }                                                  
  }           
}              

static int find_node(node *n, int k) {  
  int ret;    
  if (n == NULL) {
    ret = 0;  
  } else if (k == n->k) {
    ret = 1;
  } else if (n->l != NULL && k < n->k) {
    ret = find_node(n->l, k);
  } else if (n->r != NULL && k > n->k) {
    ret = find_node(n->r, k);              
  } else {
    ret = 0;
  }
  return ret;
}

static void print_inorder(node *n) {
  if (n->l != NULL) print_inorder(n->l);
  printf(" %d", n->k);
  if (n->r != NULL) print_inorder(n->r);
}

static void print_preorder(node *n) {
  printf(" %d", n->k);
  if (n->l != NULL) print_preorder(n->l);
  if (n->r != NULL) print_preorder(n->r);
}

static void free_node(node *n) {
  if (n == NULL) return;
  free_node(n->l);
  free_node(n->r);
  free(n);
}

