    }

  }
  else {
    if  ( s -> left  == NULL){
      x =  (NodePointer) malloc (sizeof(struct Node));
      x -> key = t;
      x -> right = NULL;
      x -> left = NULL;
      s -> left = x;
    }
    else {
      insert ( s -> left , t);
    }
  }
}


