    // 文字列を取得するための配列を宣言
    char com[16];
    // ノードの個数を取得
    scanf("%d",&n);

    for(i=0;i<n;i++) {
        // 文字列を取得
        scanf("%s",com);

        // 探すとき
        if(com[0] == 'f') {
            // 探すものを取得
            scanf("%d",&x);
            // 探し始める
            Node *t = find(root,x);
            // 返り値が空(NIL)だったらno、なんかあったらyes
            if(t != NIL) printf("yes\n");
            else printf("no\n");
        }
        // 文字列がinsertだった場合
        else if(!strcmp(com,"insert")) {
            // 挿入する数字を取得
            scanf("%d",&x);
            // 挿入する
            insert(x);
        }
        // 文字列がprintだった場合
        else if(!strcmp(com,"print")) {
            // 中間順巡回(inorder tree walk)を出力
            inorder(root);
            printf("\n");
            // 先行順巡回(preorder tree walk)を出力
            preorder(root);
            printf("\n");
        }
    }

    return 0;
}

