        y->left = z;
        ret = tree;
    } else {
        y->right = z;
        ret = tree;
    }

    return ret;
}

static int Find(const struct Node* tree, int key) {

    if ( !tree ) {
        return 0;
    }

    if ( tree->key == key ) {
        return 1;
    }
    if ( key < tree->key ) {
        return Find(tree->left, key);
    } else {
        return Find(tree->right, key);
    }
}

