struct Node {
	int key;
	struct Node* right, * left, * parent;
};
typedef struct Node* Node;

Node root;

void inorder(Node);
void preordee(Node);
void insert(int);
Node find(Node, int);

Node find(Node u, int k) {
	while (u != NIL && k != u->key) {
		if (k < u->key)u = u->left;
		else u = u->right;
	}
	return u;
}

void insert(int k) {
	Node x, y, z;
	y = NIL;
	x = root;
	z = malloc(sizeof(struct Node));
	z->key = k;
	z->left = NIL;
	z->right = NIL;
	while (x != NIL) {
		y = x;
		if (z->key < x->key) {
			x = x->left;
		}
		else {
			x = x->right;
		}
	}
	z->parent = y;
	if (y == NIL) {
		root = z;
	}
	else {
		if (z->key < y->key) {
			y->left = z;
		}
		else {
			y->right = z;
		}
	}
}

