	if (u->left != NIL && u->right != NIL) {
		inorder(u->left);
		printf(" %d", u->key);
		inorder(u->right);
	}
	if (u->left != NIL && u->right == NIL) {
		inorder(u->left);
		printf(" %d", u->key);
	}
	if (u->right != NIL && u->left == NIL) {
		printf(" %d", u->key);
		inorder(u->right);
	}
	if (u->left == NIL && u->right == NIL)printf(" %d", u->key);
}

void preorder(struct Node* u) {
	printf(" %d", u->key);
	if (u->left != NIL) {
		preorder(u->left);
	}
	if (u->right != NIL) {
		preorder(u->right);
	}
}

