		y = y->p_right;
		while (y->p_left != NULL) {
			y = y->p_left;
		}
	}
	else {
		y = z->p_parent;
	}

	/* y????????????z????????????????????? */
	z->key = y->key;

	/* y????????? */
	if (y->p_left == NULL && y->p_right == NULL) {
		deleteHasNoChildNode(y);
	}
	else{
		deleteHasOneChildNode(y);
	}
}

