void init(void)
{
    head = makenode(-1);
    tail = makenode(-1);
    head -> right = tail;
    head -> left = tail;
}

NodePointer makenode(int k)
{
    NodePointer x;

    x = malloc(sizeof(struct node));
    x -> key = k;
    x -> left = x -> right = tail;

    return x;
}

void insert(int k, NodePointer p)
{
    if(k < p -> key){
        if(p -> left == tail){
            p -> left = makenode(k);
        } else{
            insert(k, p -> left);
        }
    } else{
        if(p -> right == tail){
            p -> right = makenode(k);
        } else{
            insert(k, p -> right);
        }
    }
}

