{
    if(node != tail){
        inorder(node -> left);
        printf(" %d", node -> key);
        inorder(node -> right);
    }
}

int find(int k, NodePointer node)
{
    if(node == tail){
        return 0;
    }

    if(node -> key == k){
        return 1;
    } else if(node -> key < k){
        return find(k, node -> right);
    } else{
        return find(k, node -> left);
    }
}

