    for(int i=1;i<n;i++){
        char *command = (char*)malloc(7*sizeof(char));
        scanf("%s",command);
        if(strcmp(command,"insert")==0){
            scanf("%ld",&(node+count)->number);
            insert_node(pare,node+count);
            count++;
            pare=nn;
        }
        else if(strcmp(command,"print")==0){
            print_node(pare,1);
            printf("\n");
            print_node(pare,0);
            printf("\n");
        }
        else{
