  Node y; // node to be deleted
  Node x; // child of y
  if(z->left==NIL || z->right==NIL){ y=z;}//zが子を持たないか、子を1つ持つ場合は入力節点のz
  else {y= treeSuccessor(z);}//zが子を2つ持つ場合はzの次節点
  if(y->left!=NIL){//yの子xを決める
    x=y->left;//yに左の子があれば、xはyの左の子
