fun find(searchKey: Int): String {
    if (nodeList.count() == 0) return "no"

    var x = nodeList[0]

    while (true) {
        if (searchKey == x.key) {
            return "yes"
        }

        if (x.key < searchKey) {
            if (x.right == null) {
                return "no"
            }
            x = x.right!!
        }

        if (x.key > searchKey) {
            if (x.left == null) {
                return "no"
            }
            x = x.left!!
        }
    }
}

fun insert(addedKey: Int) {
    val addedNode = Treee(nodeList.count(), key = addedKey)

    if (nodeList.count() == 0) {
        nodeList.add(addedNode)
        return
    }

    // ルートノーのから開始
    var x = nodeList[0]
    while (true) {
        if (x.key < addedKey) {

            // 右に配置
            if (x.right == null) {
                x.right = addedNode
                break

            } else {
                x = x.right!!
            }
        } else if (x.key > addedKey) {

            // 左に配置
            if (x.left == null) {
                x.left = addedNode
                break;

            } else {
                x = x.left!!
            }

        } else {
            throw Exception("key is duplicated!!!")
        }
    }

    nodeList.add(addedNode)
}

