class Tree {

	enum Order {
		Preorder,
		Inorder,
		Postorder
	}

	Node root;

	Node insert(Node node) {
		Node parent = null;
		Node child = root;
		//
		while (child != null) {
			parent = child;
			if (node.key < child.key) child = child.left;
			else child = child.right;
		}
		node.parent = parent;
		//
		if (parent == null) {
			this.root = node;
		} else if (node.key < parent.key) {
			parent.left = node;
		} else {
			parent.right = node;
		}
		return node;
	}

	Node find(int key) {
		Node ret = null;
		Node node = root;
		while (node != null) {
			if (key != node.key) {
				if (key < node.key) node = node.left;
				else node = node.right;
			} else {
				ret = node;
				break;
			}
		}
		return ret;
	}

