	private static class BST {
		ArrayList<BSTNode> bst;
		int root;

		BST() {
			bst = new ArrayList<BSTNode>();
			root = -1;
		}

		void insert(int key) {
			bst.add(new BSTNode(key));
			int z = bst.size() - 1;
			int y = -1;
			int x = root;
			for (; x != -1; ) {
				y = x;
				if (bst.get(z).key < bst.get(x).key) {
					x = bst.get(x).l_child;
				} else {
					x = bst.get(x).r_child;
				}
			}
			bst.get(z).parent = y;
			if (y == -1) {
				root = z;
			} else {
				if (bst.get(z).key < bst.get(y).key) {
					bst.get(y).l_child = z;
				} else {
					bst.get(y).r_child = z;
				}
			}
		}

		boolean find(int key) {
			int y = -1;
			int x = root;
			for (; x != -1; ) {
				y = x;
				if (key < bst.get(x).key) {
					x = bst.get(x).l_child;
				} else if (key > bst.get(x).key) {
					x = bst.get(x).r_child;
				} else {
					return true;
				}
			}

			if (y == -1) {
				return false;
			} else {
				if (key == bst.get(y).key) {
					return true;
				} else {
					return false;
				}
			}
		}

		String preorder() {
	    	int[] order = new int[bst.size()];
	    	// Preorder
	    	if (preorder(root, order, 0) != order.length) {
	    		return "Error" + preorder(root, order, 0) + " " + order.length;
	    	}

			StringBuffer str = new StringBuffer();
			for (int i = 0; i < order.length; i++) {
				str.append(" ");
				str.append(order[i]);
			}

			return str.toString();
		}

		int preorder(int id, int[] order, int k) {
			order[k] = bst.get(id).key;
			k++;

			if (bst.get(id).l_child != -1) {
				k = preorder(bst.get(id).l_child, order, k);
			}

			if (bst.get(id).r_child != -1) {
				k = preorder(bst.get(id).r_child, order, k);
			}

			return k;

		}

		String inorder() {
	    	int[] order = new int[bst.size()];
	    	// inorder
	    	if (inorder(root, order, 0) != order.length) {
	    		return "Error" + inorder(root, order, 0) + " " + order.length;
	    	}

			StringBuffer str = new StringBuffer();
			for (int i = 0; i < order.length; i++) {
				str.append(" ");
				str.append(order[i]);
			}

			return str.toString();
		}

		int inorder(int id, int[] order, int k) {
			if (bst.get(id).l_child != -1) {
				k = inorder(bst.get(id).l_child, order, k);
			}

			order[k] = bst.get(id).key;
			k++;

			if (bst.get(id).r_child != -1) {
				k = inorder(bst.get(id).r_child, order, k);
			}

			return k;

		}

	}

	private static class BSTNode {
		public int key;
		public int parent;
		public int l_child;
		public int r_child;

		public BSTNode(int key) {
			this.key = key;
			this.parent = -1;
			this.l_child = -1;
			this.r_child = -1;
		}
	}


