class Tree {
    Node root;

    private class Node {
        Node parent;
        Node left;
        Node right;
        int data;

        public Node(int data) {
            this.data = data;
            parent = null;
            left = null;
            right = null;
        }

        boolean isLeaf() {
            return left == null && right == null;
        }

        String preorder() {
            if (isLeaf()) {
                return " " + data;
            } else if (left == null) {
                return " " + data + right.preorder();
            } else if (right == null) {
                return " " + data + left.preorder();
            } else {
                return " " + data + left.preorder() + right.preorder();
            }
        }

        String inorder() {
            if (isLeaf()) {
                return " " + data;
            } else if (left == null) {
                return " " + data + right.inorder();
            } else if (right == null) {
                return left.inorder() + " " + data;
            } else {
                return left.inorder() + " " + data + right.inorder();
            }
        }
    }

    public Tree() {
        root = null;
    }

    public void insert(int data) {
        Node parent = null;
        Node node = root;
        Node newNode = new Node(data);
        while (node != null) {
            parent = node;
            if (data < node.data) {
                node = node.left;
            } else {
                node = node.right;
            }
        }

        newNode.parent = parent;

        if (parent == null) {
            root = newNode;
        } else if (newNode.data < parent.data) {
            parent.left = newNode;
        } else {
            parent.right = newNode;
        }
    }

    public boolean find(int data) {
        Node node = root;
        while (node != null) {
            if (node.data == data) {
                return true;
            }

            if (data < node.data) {
                node = node.left;
            } else {
                node = node.right;
            }
        }
        return false;
    }

    public String print() {
        return inorder() + "\n" + preorder();
    }

    public String preorder() {
        return root.preorder();
    }

    public String inorder() {
        return root.inorder();
    }
}

