    this.left = null;
    this.right = null;
  }

  public void insert(int x) {
    if (x < this.value) {
      if (left == null) {
        left = new Node(x);
        return;
      } else {
        left.insert(x);
        return;
      }
    } else {
      if (right == null) {
        right = new Node(x);
        return;
      } else {
        right.insert(x);
        return;
      }
    }
  }

  public boolean find(int key) {
    if (this.value == key) {
      return true;
    } else if (key < this.value) {
      if(left == null) {
        return false;
      } else {
        return left.find(key);
      }
    } else if (key > this.value) {
      if (right == null) {
        return false;
      } else {
        return right.find(key);
      }
    }
    // never come here
    return false;
  }

  public void printInOrder(){
    if (left != null) {
      left.printInOrder();
    }

    process();

    if (right != null) {
      right.printInOrder();
    }
  }

  public void printPreOrder(){
    process();

    if (left != null) {
      left.printPreOrder();
    }

    if (right != null) {
