class Tree {
	Node root;



	void insert(Node z) {
		Node y = null; // parent of x
		Node x = this.root; // the root of Tree

		while (x != null) {
			y = x;
			if (z.key < x.key) {
				x = x.left;
			} else {
				x = x.right;
			}
		}
		z.parent = y;

		if (y == null) {
			this.root = z;
		} else {
			if (z.key < y.key) {
				y.left = z;
			} else {
				y.right = z;
			}
		}
	}

	boolean find(int key, Node currentNode) {
		if (currentNode == null) {
			return false;
		}
		if (currentNode.key == key) {
			return true;
		}
		if (currentNode.key > key) {
			return find(key, currentNode.left);
		} else {
			return find(key, currentNode.right);
		}
	}
}

