			return;
		}

		inorder(node.left, ret);
		ret.add(node.key);
		inorder(node.right, ret);
	}

	private static void preorder(Node node, List<Integer> ret) {
		if (node == null) {
			return;
		}

		ret.add(node.key);
		preorder(node.left, ret);
		preorder(node.right, ret);
	}

	private static void insert(Node z) {
