class Node {
  Node left;
  Node right;
  int value;

  public Node (int x) {
    this.value = x;
    this.left = null;
    this.right = null;
  }

  public void insert(int x) {
    if (x < this.value) {
      if (left == null) {
        left = new Node(x);
        return;
      } else {
        left.insert(x);
        return;
      }
    } else {
      if (right == null) {
        right = new Node(x);
        return;
      } else {
        right.insert(x);
        return;
      }
    }
  }

  public boolean find(int key) {
    if (this.value == key) {
      return true;
    } else if (key < this.value) {
      if(left == null) {
        return false;
      } else {
        return left.find(key);
      }
    } else if (key > this.value) {
      if (right == null) {
        return false;
      } else {
        return right.find(key);
      }
    }
    // never come here
    return false;
  }

  public void printInOrder(){
    if (left != null) {
      left.printInOrder();
    }

    process();

    if (right != null) {
      right.printInOrder();
    }
  }

  public void printPreOrder(){
    process();

    if (left != null) {
      left.printPreOrder();
    }

    if (right != null) {
      right.printPreOrder();
    }
  }


  private void process() {
    System.out.print(" ");
    System.out.print(value);
  }
}

class BinaryTree {
  Node root;

  public BinaryTree() {}

  public void insert(int x) {
    if (root == null) {
      root = new Node(x);
      return;
    }

    if (x < root.value) {
      if (root.left == null) {
        root.left = new Node(x);
        return;
      } else {
        root.left.insert(x);
        return;
      }
    } else {
      if (root.right == null) {
        root.right = new Node(x);
        return;
      } else {
        root.right.insert(x);
        return;
      }
    }
  }

  public void find(int key) {
    if (root != null) {
      boolean found = root.find(key);
      if (found) {
        System.out.println("yes");
        return;
      }
    }
    System.out.println("no");
  }

  public void printInOrder() {
    if (root != null) {
      root.printInOrder();
    }
    System.out.println();
  }

  public void printPreOrder() {
    if (root != null) {
      root.printPreOrder();
    }
    System.out.println();
  }

