        }

        public String next() {
            nextToken();
            return st.sval;
        }

        public Integer nextInt() {
            nextToken();
            return (int)st.nval;
        }

        private int nextToken() {
            int token = st.TT_EOF;
            try {
                token = st.nextToken();
            } catch (IOException e) {
            }
            return token;
        }
    }
}

