	public Main() {
		root = null;
	}
	public Node insert(Integer key) {
		Node p = root;
		Node parent = null;
		boolean isLeftChild = false;
		while(p != null) {
			int result = key.compareTo(p.data);
			if(result == 0) {
				return null;
			}else if(result < 0) {
				parent = p;
				isLeftChild = true;
				p = p.left;
			}else {
				parent = p;
				isLeftChild = false;
				p = p.right;
			}
		}
		Node newNode = new Node(key);
		if(parent == null) {
			root = newNode;
		}else if(isLeftChild) {
			parent.left = newNode;
		}else {
			parent.right = newNode;
		}
		return newNode;
	}

	//二分探索木からkeyをもつ節を探索するメソッド
	//Javaプログラマのためのアルゴリズムとデータ構造 p.224参照
	public Node search(Integer key) {
		//まず根に注目する
		Node p = root;

		//注目している節がある限り繰り返し処理を行う
		while(p != null) {

			//注目している節とkeyを比較する
			int result = key.compareTo(p.data);

			//節とkeyが等しい
			if(result == 0) {
				return p;

			//keyの方が小さいときは左分木に進む
			}else if(result < 0) {
				p = p.left;

			//keyの方が大きいときは右分木に進む
			}else {
				p = p.right;
			}
		}
		//探索に失敗したらnullを返す
		return null;
	}
