        Node x = root;
        boolean ans = false;

        while(x !=null){
            if(x.key == key){
                ans = true;
                break;
            } else if(x.key<key){
                x = x.rightChild;
            } else if(x.key>key){
                x = x.leftChild;
            }
        }
        System.out.println(ans ? "yes" : "no");
    }

    public static void insert(Node root, int key) {
        // xとxParentを木の下に移動していく
        Node x = root;
        Node y = new Node(key);
        Node xParent = null;

        if(x.key == null){
            x.key = y.key; //x = y x.keyの値が変更できないことに注意。xに入っているのはあくまでアドレス値
            return;
        }

        while(x != null){
            xParent = x;
            if(x.key < y.key){
                x = x.rightChild;
            } else {
                x = x.leftChild;
            }
        }

        y.parent = xParent;
        if(xParent == null){
            x = y;
        }else if(xParent.key<y.key){
            xParent.rightChild = y;
        }else if(xParent.key>y.key){
            xParent.leftChild = y;
        }

    }

