    class BinarySearchTree
    {
        public Node Root { get; set; }
        public BinarySearchTree()
        {
            Root = null;
        }

        public void Insert(Node node)
        {
            Node parent = null;
            Node current = Root;

            while (current != null)
            {
                parent = current;
                if (node.Key < current.Key)
                    current = current.Left;
                else
                    current = current.Right;
            }

            if (parent == null)
            {
                Root = node;
            }

            else if (node.Key < parent.Key)
            {
                parent.Left = node;
                node.Parent = parent;
            }

            else
            {
                parent.Right = node;
                node.Parent = parent;
            }
        }

        public Node Find(Node node)
        {
            Node current = Root;

            while (current != null)
            {
                if (node.Key == current.Key)
                    break;

                if (node.Key < current.Key)
                    current = current.Left;
                else
                    current = current.Right;
            }

            return current;
        }

        /// <summary>
        /// ????????¢?´¢??¨?????????????????\????????¢?????´?????????????????????
        /// 1.???????????????: ????±??????????????????????
        /// 2.????????????: ????±??????????????????????????????¨????????????????????????
        /// 3.????????????: ????±??????????????¬??????????????????????????±??????????????????????????¬?????????????????????£??\?????????
        ///            ????¬???????: ??¨??????????????????????????´?????????????±??????????????¬????????????????
        /// </summary>

        public void Delete(Node node)
        {
            Node deleted = null;
            if (node.Left == null || node.Right == null)
                // ??????????????\????????´?????????node???????????????????±????
                deleted = node;
            else
                // ?????????????????´??????????¬????????????????????±????
                deleted = GetSuccessor(node);

            Node child = null;
            if (deleted.Left != null)
                child = deleted.Left;
            else
                child = deleted.Right;

            if (child != null)
                // (?????????????????´????????????????????????)
                child.Parent = deleted.Parent;

            if (deleted.Parent == null)
                Root = child;
            else if (deleted == deleted.Parent.Left)
                deleted.Parent.Left = child;
            else
                deleted.Parent.Right = child;

            if (deleted != node)
                // (?????????????????´???)
                // ???????????????????§?????????????
                node.Key = deleted.Key;
        }

        /// <summary>
        /// ????????????????????¨???????¬???????????±??????????
        /// </summary>
        /// <returns></returns>
        protected Node GetSuccessor(Node node)
        {
            if (node.Right != null)
                // ????????????????????´???????????¨?????¨???????°????????¬??????????
                return GetMinimum(node);

            // ??????????????????????????´????????????????????????????????????????????????????±??????????
            Node parent = node.Parent;
            while (parent != null && node == parent.Right)
            {
                node = parent;
                parent = parent.Parent;
            }
            return parent;
        }

        protected Node GetMinimum(Node node)
        {
            if (node.Left == null)
                return node;
            return GetMinimum(node.Left);
        }

        public void ApplyPreorder(Node node, Action<Node> func)
        {
            if (node == null) return;

            func(node);
            ApplyPreorder(node.Left, func);
            ApplyPreorder(node.Right, func);
        }

        public void ApplyInorder(Node node, Action<Node> func)
        {
            if (node == null) return;

            ApplyInorder(node.Left, func);
            func(node);
            ApplyInorder(node.Right, func);
        }

        public void ApplyPostorder(Node node, Action<Node> func)
        {
            if (node == null) return;

            ApplyPostorder(node.Left, func);
            ApplyPostorder(node.Right, func);
            func(node);
        }
    }

