namespace Forest {
	class TreeNode<T> {
		public virtual TreeNode<T> Parent { get; set; }
		public T Value { get; set; }
		public int Id { get; set; }
		public int Order { get; set; }
		public virtual List<TreeNode<T>> Children { get; set; } = new List<TreeNode<T>>();
		public virtual bool isRoot { get { return Parent==null; } }
		public virtual bool isLeaf { get { return !Children.Any(); } }
		public bool isInternal { get { return !isRoot&&!isLeaf; } }
		public virtual int Depth {
			get {
				var count = 0;
				var P = this;
				while(!P.isRoot) {
					P=P.Parent;
					count++;
				}
				return count;
			}
		}
		public int Height {
			get {
				if(isLeaf) return 0;
				return Children.Select(X => X.Height).Max()+1;
			}
		}
		public virtual int Degree { get { return Children.Count(); } }

		public void AdoptMany(List<TreeNode<T>> children) {
			Children=children;
			foreach(var node in children)
				node.Parent=this;
		}
		public void AdoptMany(TreeNode<T>[] Base, IEnumerable<int> call) {
			var children = call.Select(k => Base[k]).ToList();
			AdoptMany(children);
		}
		public void Adopt(TreeNode<T> child) {
			Children.Add(child);
			child.Parent=this;
		}
	}
	class BinNode<T>: TreeNode<T> {
		public new BinNode<T> Parent { get; set; }
		public BinNode<T> Left { get; set; }
		public BinNode<T> Right { get; set; }
		public new List<BinNode<T>> Children {
			get { return new BinNode<T>[] { Left, Right }.Where(x => x!=null).ToList(); }
		}
		public override int Depth {
			get {
				var count = 0;
				var P = this;
				while(!P.isRoot) {
					P=P.Parent;
					count++;
				}
				return count;
			}
		}
		public new bool isRoot { get { return Parent==null; } }
		public override bool isLeaf { get { return Left==null&&Right==null; } }
		public override int Degree {
			get { return (Left!=null ? 1 : 0)+(Right!=null ? 1 : 0); }
		}
		public void Adopt(BinNode<T> left, BinNode<T> right) {
			Left=left; Right=right;
			if(left!=null) left.Parent=this; if(right!=null) right.Parent=this;
		}
		public BinNode<T> Sibling {
			get { return isRoot ? null : Equals(Parent.Left) ? Parent.Right : Parent.Left; }
		}
		public static void GetHeight(BinNode<T>[] Nodes, out int[] Res) {
			Res=new int[Nodes.Length];
			foreach(var root in Nodes.Where(n => n.isRoot)) {
				GetHeight(root, Res);
			}
		}
		private static void GetHeight(BinNode<T> now, int[] Res) {
			if(now.isLeaf||!now.Children.Any()) { Res[now.Id]=0; return; }
			foreach(var child in now.Children) {
				GetHeight(child, Res);
			}
			Res[now.Id]=now.Children.Max(c => Res[c.Id])+1;
		}
		internal static void DFS(BinNode<T> now,
			Func<BinNode<T>, bool> OnEnter, Func<BinNode<T>, bool> OnMiddle, Func<BinNode<T>, bool> OnLeave
		) {
			if(now==null) return;
			if(OnEnter?.Invoke(now)==true) return;
			DFS(now.Left, OnEnter, OnMiddle, OnLeave);
			if(OnMiddle?.Invoke(now)==true) return;
			DFS(now.Right, OnEnter, OnMiddle, OnLeave);
			if(OnLeave?.Invoke(now)==true) return;
		}
		internal static void DFS(BinNode<T> now,
			Action<BinNode<T>> OnEnter, Action<BinNode<T>> OnMiddle, Action<BinNode<T>> OnLeave
		) {
			if(now==null) return;
			OnEnter?.Invoke(now);
			DFS(now.Left, OnEnter, OnMiddle, OnLeave);
			OnMiddle?.Invoke(now);
			DFS(now.Right, OnEnter, OnMiddle, OnLeave);
			OnLeave?.Invoke(now);
		}
		public void PreLabel() {
			var count = 0;
			DFS(this, b => b.Order=count++, null, null);
		}
		public void InLabel() {
			var count = 0;
			DFS(this, null, b => b.Order=count++, null);
		}
		public void PostLabel() {
			var count = 0;
			DFS(this, null, null, b => b.Order=count++);
		}
		public List<BinNode<T>> PreOrder() {
			var order = new List<BinNode<T>>();
			DFS(this, b => order.Add(b), null, null);
			return order;
		}
		public List<BinNode<T>> InOrder() {
			var order = new List<BinNode<T>>();
			DFS(this, null, b => order.Add(b), null);
			return order;
		}
		public List<BinNode<T>> PostOrder() {
			var order = new List<BinNode<T>>();
			DFS(this, null, null, b => order.Add(b));
			return order;
		}
		internal BinNode<T> Leftest() {
			if(this==null) return null;
			var tmp = this;
			while(tmp.Left!=null)
				tmp=tmp.Left;
			return tmp;
		}
		internal bool isLeftSide() => this==Parent?.Left;
		internal bool isRightSide() => this==Parent?.Right;
		internal void ReAdopt(BinNode<T> neo) {
			if(isLeftSide()) Parent.Left=neo;
			else if(isRightSide()) Parent.Right=neo;
		}
		internal void ClearRelation() { Parent=null; Left=null; Right=null; }
		internal static void SwapRelation(BinNode<T> X, BinNode<T> Y) {
			var tmp = X.Parent; X.Parent=Y.Parent; Y.Parent=tmp;
			tmp=X.Left; X.Left=Y.Left; Y.Left=tmp;
			tmp=X.Right; X.Right=Y.Right; Y.Right=tmp;
		}
	}
	class BinarySearchTree<T> where T : IComparable<T> {
		public BinNode<T> Root { get; private set; }
		public int count { get; set; } = 0;
		public Comparer<T> comparer { get; } = Comparer<T>.Create((i, j) => i.CompareTo(j));
		private int Collate(T a, T b) => comparer.Compare(a, b);
		private int Collate(BinNode<T> A, BinNode<T> B)
			=> Collate(A.Value, B.Value);
		public void Insert(T value)
			=> Insert(new BinNode<T> { Value=value, Id=count++ });
		public void Insert(BinNode<T> newComer) {
			var newParent = default(BinNode<T>);
			var parentDetector = Root;
			while(parentDetector!=null) {
				newParent=parentDetector;
				parentDetector=
					Collate(newComer, parentDetector)<0 ? parentDetector.Left : parentDetector.Right;
			}
			newComer.Parent=newParent;

			if(newParent==null) {
				Root=newComer;
			} else if(Collate(newComer, newParent)<0) {
				newParent.Left=newComer;
			} else {
				newParent.Right=newComer;
			}
		}
		public bool Contains(T value) => Search(value)!=null;
		private BinNode<T> Search(T value) {
			var tmp = Root;
			while(tmp!=null) {
				var collation = Collate(value, tmp.Value);
				if(collation==0) return tmp;
				else tmp=collation<0 ? tmp.Left : tmp.Right;
			}
			return null;
		}
		//TODO: Incomplete
		public void Delete(BinNode<T> t) {
			var p = t.Parent;
			switch(t.Children.Count()) {
				case 0:
					if(t.isLeftSide())
						p.Left=null;
					else if(t.isRightSide())
						p.Right=null;
					else
						Root=t;
					break;
				case 1:
					var Child = t.Children.First();
					t.ReAdopt(Child);
					Child.Parent=p;
					break;
				case 2:
					var Next = t.Right.Leftest();
					BinNode<T>.SwapRelation(Next, t);
					break;
			}
			t.ClearRelation();
		}
		public void DFS(
			Func<BinNode<T>, bool> OnEnter, Func<BinNode<T>, bool> OnMiddle, Func<BinNode<T>, bool> OnLeave
		) {
			BinNode<T>.DFS(Root, OnEnter, OnMiddle, OnLeave);
		}
		public void DFS(
			Action<BinNode<T>> OnEnter, Action<BinNode<T>> OnMiddle, Action<BinNode<T>> OnLeave
		) {
			BinNode<T>.DFS(Root, OnEnter, OnMiddle, OnLeave);
		}
	}
