class Program{
    class Node{
        public int key;
        public Node parent;
        public Node left;
        public Node right;
    }

    static void Insert(Node root, Node z){
        Node y=null;
        var x=root.left;
        while (x!=null) {
            y=x;
            if (z.key<x.key) {
                x=x.left;
            } else {
                x=x.right;
            }
        }
        z.parent=y;
        if (y==null) {
            root.left=z;
        } else if (z.key<y.key) {
            y.left=z;
        } else {
            y.right=z;
        }
    }

    static bool Find(Node node, int key){
        if (node.key==key) {
            return true;
        } else {
            if (node.key>key) {
                return node.left!=null && Find(node.left, key);
            } else {
                return node.right!=null && Find(node.right, key);
            }
        }
    }

    static void WalkPreorder(Node node){
        Console.Write(" "+node.key);
        if(node.left!=null){
            WalkPreorder(node.left);
        }
        if(node.right!=null){
            WalkPreorder(node.right);
        }
    }

    static void WalkInorder(Node node){
        if(node.left!=null){
            WalkInorder(node.left);
        }
        Console.Write(" "+node.key);
        if(node.right!=null){
            WalkInorder(node.right);
        }
    }

    public static void Main(){
        var m=int.Parse(Console.ReadLine());
        var root=new Node();
        for (var i=0; i<m; i++) {
            var s=Console.ReadLine().Split(' ');
            if (s[0][0]=='i') {
                var node=new Node();
                node.left=null;
                node.right=null;
                node.key=int.Parse(s[1]);
                Insert(root, node);
            } else if (s[0][0]=='f') {
                Console.WriteLine(Find(root.left, int.Parse(s[1])) ?
                        "yes" : "no");
            } else {
                WalkInorder(root.left);
                Console.WriteLine();
                WalkPreorder(root.left);
                Console.WriteLine();
            }
        }
    }
}

