namespace Binary_search_trees
{
    class Binary_Search_Tree_II
    {
        class BinaryTree
        {
            public class Node
            {
                internal int val;
                internal Node left, right, parent;

                internal Node() : this(0, null) { }

                internal Node(int val, Node parent)
                {
                    this.val = val;
                    this.parent = parent;
                    left = right = null;
                }
            }

            Node root;

            public BinaryTree()
            {
                root = null;
            }

            public void Insert(int elem)
            {
                if (root == null)
                {
                    root = new Node(elem, null);
                    return;
                }

                Node n = root;
                Node p = null;
                while (n != null)
                {
                    p = n;
                    if (n.val > elem) n = n.left;
                    else n = n.right;
                }

                n = new Node(elem, p);
                if (p.val > elem) p.left = n;
                else p.right = n;
            }
            public Node Find(int elem)
            {
                Node n = root;
                while (n != null)
                {
                    if (n.val > elem) n = n.left;
                    else if (n.val < elem) n = n.right;
                    else break;
                }
                return n;
            }

            public bool Contains(int elem)
            {
                return Find(elem) != null;
            }

            public void PrintPreorder(Node n)
            {
                if (n == null) return;
                Console.Write(" " + n.val);
                PrintPreorder(n.left);
                PrintPreorder(n.right);
            }

            public void PrintPreorder()
            {
                PrintPreorder(root);
                Console.WriteLine();
            }

            public void PrintInorder(Node n)
            {
                if (n == null) return;
                PrintInorder(n.left);
                Console.Write(" " + n.val);
                PrintInorder(n.right);
            }

            public void PrintInorder()
            {
                PrintInorder(root);
                Console.WriteLine();
            }
        }

        static void Main(string[] args)
        {
            var n = int.Parse(Console.ReadLine());
            var bt = new BinaryTree();
            var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            Console.SetOut(sw);
            for (int i = 0; i < n; i++)
            {
                var line = Console.ReadLine();
                switch (line[0])
                {
                    case 'i':
                        bt.Insert(int.Parse(line.Substring(7)));
                        break;
                    case 'f':
                        if (bt.Contains(int.Parse(line.Substring(5)))) Console.WriteLine("yes");
                        else Console.WriteLine("no");
                        break;
                    case 'p':
                        bt.PrintInorder();
                        bt.PrintPreorder();
                        break;
                }
            }
            Console.Out.Flush();
        }
    }
}

