func main() {
	reader := bufio.NewReader(os.Stdin)

	var root *node
	m := eGetInt(reader)
	for i := 0; i < m; i++ {
		line := eGetline(reader)
		elements := strings.Fields(line)
		if len(elements) == 1 {
			// print
			var buffer bytes.Buffer
			printInOrder(root, &buffer)
			fmt.Println(buffer.String())
			buffer.Reset()

			printPreOrder(root, &buffer)
			fmt.Println(buffer.String())
			buffer.Reset()
		} else {
			val := eAtoi(elements[1])
			if strings.HasPrefix(line, "insert") {
				root = insert(root, val)
			} else if strings.HasPrefix(line, "find") {
				if find(root, val) {
					fmt.Println("yes")
				} else {
					fmt.Println("no")
				}
			}
		}
	}
}

func insert(root *node, value int) *node {
	var y *node
	x := root
	for x != nil {
		y = x // 親を覚えておく
		if value < x.value {
			x = x.left
		} else {
			x = x.right
		}
	}
	x = &node{value, y, nil, nil}
	if y == nil {
		return x
	} else if x.value < y.value {
		y.left = x
	} else {
		y.right = x
	}
	return root
}
func find(root *node, value int) bool {
	x := root
	for x != nil {
		if x.value == value {
			return true
		}

		if value < x.value {
			x = x.left
		} else {
			x = x.right
		}
	}
	return false
}

func printInOrder(root *node, buf *bytes.Buffer) {
	if root.left != nil {
		printInOrder(root.left, buf)
	}
	buf.WriteString(fmt.Sprintf(" %d", root.value))
	if root.right != nil {
		printInOrder(root.right, buf)
	}
}
func printPreOrder(root *node, buf *bytes.Buffer) {
	buf.WriteString(fmt.Sprintf(" %d", root.value))
	if root.left != nil {
		printPreOrder(root.left, buf)
	}
	if root.right != nil {
		printPreOrder(root.right, buf)
	}
}

func eGetInt(reader *bufio.Reader) int {
	return eAtoi(eGetline(reader))
}

func eGetline(o *bufio.Reader) string {
	s, err := o.ReadString(byte('\n'))
	if err != nil {
		if err == io.EOF {
			return s
		}
		log.Fatal(err.Error())
	}
	return strings.TrimRight(s, "\r\n")
}
func eAtoi(s string) int {
	v, err := strconv.Atoi(s)
	if err != nil {
		log.Fatal(err.Error())
	}
	return v
}

