		return z
	}

	var x, y *Node
	x = root
	for x != nil {
		y = x
		if k < x.Value {
			x = x.Left
		} else {
			x = x.Right
		}
	}

	z.Parent = y
	if k < y.Value {
		y.Left = z
	} else {
		y.Right = z
	}
	return root
}

