	n := getNextInt(scanner)

	var tree Tree

	tree.root = nil

	for i := 0; i < n; i++ {
		order := getNextString(scanner)
		switch order {
		case "print":
			tree.i = 0
			tree.keys = make([]int, tree.n)
			tree.printInOrders(tree.root)
			fmt.Fprintln(writer, fmt.Sprintf(" %s", joinint(tree.keys, " ")))
			tree.i = 0
			tree.keys = make([]int, tree.n)
			tree.printPreOrders(tree.root)
			fmt.Fprintln(writer, fmt.Sprintf(" %s", joinint(tree.keys, " ")))
		case "insert":
			key := getNextInt(scanner)
			tree.insert(key)
		case "find":
			key := getNextInt(scanner)
			if tree.find(key) {
				fmt.Fprintln(writer, "yes")
