// https://onlinejudge.u-aizu.ac.jp/courses/lesson/1/ALDS1/all/ALDS1_8_A

type Node struct {
	key                 int
	right, left, parent *Node
}

var root *Node

func Insert(k int) {
	var y *Node
	y = nil   // xの親
	x := root // 挿入先
	z := new(Node)
	z.key, z.left, z.right = k, nil, nil

	// 挿入先の探索
	for x != nil {
		y = x
		if z.key < x.key {
			x = x.left
		} else {
			x = x.right
		}
	}

	// 挿入ノードに関して、親と挿入先を設定する（挿入先の判断にはもう一度kyeチェックが必要）
	z.parent = y
	if y == nil {
		root = z
	} else {
		if z.key < y.key {
			y.left = z
		} else {
			y.right = z
		}
	}
}

// keyのノードが見つからなかった場合はnilを返す
func Find(k int) *Node {
	u := root
	for u != nil && k != u.key {
		if k < u.key {
			u = u.left
		} else {
			u = u.right
		}
	}
	return u
}

func inorder(u *Node, res *[]int) {
	if u == nil {
		return
	}
	inorder(u.left, res)
	*res = append(*res, u.key)
	inorder(u.right, res)
}

func preorder(u *Node, res *[]int) {
	if u == nil {
		return
	}
	*res = append(*res, u.key)
	preorder(u.left, res)
	preorder(u.right, res)
}

func main() {
	n := ReadInt()

	for i := 0; i < n; i++ {
		s := ReadString()
		if s == "insert" {
			k := ReadInt()
			Insert(k)
		} else if s == "print" {
			res := []int{}
			inorder(root, &res)
			fmt.Printf(" ")
			fmt.Println(PrintIntsLine(res...))
			res = []int{}
			preorder(root, &res)
			fmt.Printf(" ")
			fmt.Println(PrintIntsLine(res...))
		} else if s == "find" {
			k := ReadInt()
			n := Find(k)
			if n != nil {
				fmt.Println("yes")
			} else {
				fmt.Println("no")
			}
		}
	}
}

