func (n *Node) find(k int) *Node {
	for n != nil && n.key != k {
		if n.key > k {
			n = n.left
			continue
		}
		n = n.right
	}
	return n
}

func (n *Node) insert(k int) {
	root := n
	var target *Node
	node := &Node{key: k, left: nil, right: nil}

	for root != nil {
		target = root
		if root.key > k {
			root = root.left
			continue
		}
		root = root.right
	}

	if target.key > node.key {
		target.left = node
		return
	}
	target.right = node
}

func (n *Node) inorder() {
	if n == nil {
		return
	}
	n.left.inorder()
	if n.key != 0 {
		out.WriteString(fmt.Sprintf(" %d", n.key))
	}
	n.right.inorder()
}

func (n *Node) preorder() {
	if n == nil {
		return
	}
	if n.key != 0 {
		out.WriteString(fmt.Sprintf(" %d", n.key))
	}
	n.left.preorder()
	n.right.preorder()
}

func answer(reader io.Reader) string {
	root := &Node{}

	sc := bufio.NewScanner(reader)
	sc.Split(bufio.ScanWords)

