		switch sc.Text() {
		case "insert":
			sc.Scan()
			k, _ := strconv.Atoi(sc.Text())
			root.insert(k)
		case "print":
			root.inorder()
			out.WriteString("\n")
			root.preorder()
			out.WriteString("\n")
		case "find":
			sc.Scan()
			k, _ := strconv.Atoi(sc.Text())
			t := root.find(k)
			if t != nil {
				out.WriteString("yes\n")
			} else {
				out.WriteString("no\n")
			}
		}
	}

	return strings.TrimRight(out.String(), "\n")
}

