	node := &Node{key: v, left: dummy, right: dummy}

	parent := dummy
	leaf := dummy.left
	for leaf != dummy {
		parent = leaf
		if node.key < leaf.key {
			leaf = leaf.left
		} else {
			leaf = leaf.right
		}
	}

	node.parent = parent
	if parent == dummy {
		dummy.left = node
		dummy.right = node
	} else if node.key < parent.key {
		parent.left = node
	} else {
		parent.right = node
	}
}

func preOrder(node *Node, w io.Writer) {
	if node == dummy {
		return
	}

	fmt.Fprint(w, " ", node.key)
	preOrder(node.left, w)
	preOrder(node.right, w)
