func insert(tree **node, z *node) {
	// zの親になるノードをyとする
	var y *node
	// zの親になるノードを探す
	x := *tree
	for x != nil {
		y = x //仮親を設定
		if z.key < x.key {
			x = x.left
		} else {
			x = x.right
		}
	}
	z.parent = y  // zの親をyにする
	if y == nil { // tが空の場合(木に追加される最初の要素)
		*tree = z
	} else if z.key < y.key {
		y.left = z // zをyの左の子にする
	} else {
		y.right = z // zをyの右の子にする
	}
