func Print(nodes []int) {
	// 木の走査によって得られたint型スライスを引数に、
	// 指定されたフォーマットに出力する関数
	writer := bufio.NewWriter(os.Stdout)
	for _, v := range nodes {
		writer.Write([]byte(fmt.Sprintf(" %d", v)))
	}
	writer.Write([]byte("\n"))
	writer.Flush()
}
func Insert(root *node, value int) *node {

	if root == nil {
		return &node{value, nil, nil}
	}

	var parent *node
	anode := root
	for anode != nil {
		parent = anode
		if anode.key > value {
			anode = anode.left
		} else {
			anode = anode.right
		}
	}

	if parent.key > value {
		parent.left = &node{value, nil, nil}
	} else {
		parent.right = &node{value, nil, nil}
	}
	return root
}
func Inorder(root *node, store []int) []int {
	if root != nil {
		store = Inorder(root.left, store)
		store = append(store, root.key)
		store = Inorder(root.right, store)
	}
	return store
}
func Preorder(root *node, store []int) []int {
	if root != nil {
		store = append(store, root.key)
		store = Preorder(root.left, store)
		store = Preorder(root.right, store)
	}
	return store
}
func Find(root *node, value int) bool {
	if root == nil {
		return false
	}
	if root.key == value {
		return true
	}
	if root.key > value {
		return Find(root.left, value)
	}
	return Find(root.right, value)
}
