func insert(root *elem, zkey int) *elem {
	// new Value
	z := &elem{nil, nil, nil, zkey}
	if root == nil {
		return z
	}

	// search parent
	parentOfZ := root
	for {
		if parentOfZ.key > z.key {
			if parentOfZ.left == nil {
				parentOfZ.left = z
				break
			}
			parentOfZ = parentOfZ.left
		} else {
			if parentOfZ.right == nil {
				parentOfZ.right = z
				break
			}
			parentOfZ = parentOfZ.right
		}
	}

	z.paremnt = parentOfZ
	return root
}

