	// search parent
	s := root
	for {

		if s.key == zkey {
			return "yes"
		}

		if s.key > zkey {
			if s.left == nil {
				break
			}
			s = s.left
		} else {
			if s.right == nil {
				break
			}
			s = s.right
		}
	}
	return "no"
}

