type Node struct {
	key    int
	parent *Node
	left   *Node
	right  *Node
}

var root *Node

func insert(z *Node) {
	var y *Node
	x := root
	for x != nil {
		y = x
		if z.key < y.key {
			x = y.left
		} else {
			x = y.right
		}
	}
	z.parent = y
	if y == nil {
		root = z
	} else if z.key < y.key {
		y.left = z
	} else {
		y.right = z
	}
}

func find(k int) bool {
	n := root
	for n != nil {
		if n.key == k {
			return true
		} else if k < n.key {
			n = n.left
		} else if n.key < k {
			n = n.right
		}
	}
	return false
}

func printByInOrder(w io.Writer, n *Node) {
	if n.left != nil {
		printByInOrder(w, n.left)
	}
	fmt.Fprint(w, " ", n.key)
	if n.right != nil {
		printByInOrder(w, n.right)
	}
}

func printByPreOrder(w io.Writer, n *Node) {
	fmt.Fprint(w, " ", n.key)
	if n.left != nil {
		printByPreOrder(w, n.left)
	}
	if n.right != nil {
		printByPreOrder(w, n.right)
	}
}

