func preorder(u *Node, l []int) []int {
	if u != NIL {

		//fmt.Printf(" %d", u.key)
		l = append(l, u.key)
		l = preorder(u.l, l)
		l = preorder(u.r, l)
	}
	return l

}

func inorder(u *Node, l []int) []int {
	if u != NIL {
		l = inorder(u.l, l)
		//fmt.Printf(" %d", u.key)
		l = append(l, u.key)
		l = inorder(u.r, l)
	}
	return l
}

