func binarySearch(x int, s []int) bool {
	left, mid, right := 0, 0, len(s)-1
	for left < right {
		mid = (right + left) / 2
		if s[mid] == x {
			return true
		} else {
			if s[mid] < x {
				left = mid + 1
			} else {
				right = mid
			}
		}
	}
	return false
}

