type Element struct {
	parent, left, right *Element
	key                 int
}

// NewBinarySearchTree is constructor for BinarySearchTree
func NewBinarySearchTree() *BinarySearchTree {
	bstree := BinarySearchTree{
		root: nil,
	}
	return &bstree
}

// BinarySearchTree for int
type BinarySearchTree struct {
	root *Element
}

func (t *BinarySearchTree) inorderTreeWalk(p *Element) string {
	if p == nil {
		return ""
	}

	return t.inorderTreeWalk(p.left) +
		" " + strconv.Itoa(p.key) +
		t.inorderTreeWalk(p.right)
}

func (t *BinarySearchTree) preorderTreeWalk(p *Element) string {
	if p == nil {
		return ""
	}

	return " " + strconv.Itoa(p.key) +
		t.preorderTreeWalk(p.left) +
		t.preorderTreeWalk(p.right)
}

func (t *BinarySearchTree) insert(k int) {
	newElement := Element{
		left:  nil,
		right: nil,
		key:   k,
	}

	x := t.root
	var y *Element

	for x != nil {
		y = x
		if newElement.key < x.key {
			x = x.left
		} else {
			x = x.right
		}
	}
	newElement.parent = y
	if y == nil {
		t.root = &newElement
	} else if newElement.key < y.key {
		y.left = &newElement
	} else {
		y.right = &newElement
	}
}

func (t *BinarySearchTree) search(current *Element, k int) *Element {
	for current != nil && current.key != k {
		if k < current.key {
			current = current.left
		} else {
			current = current.right
		}
	}
	return current
}

func (t *BinarySearchTree) minimum(x *Element) *Element {
	for x.left != nil {
		x = x.left
	}
	return x
}

func (t *BinarySearchTree) maximum(x *Element) *Element {
	for x.right != nil {
		x = x.right
	}
	return x
}

func (t *BinarySearchTree) successor(x *Element) *Element {
	if x.right != nil {
		return t.minimum(x.right)
	}
	y := x.parent
	for y != nil && x == y.right {
		x = y
		y = y.parent
	}
	return y
}

