class Node(T)
{
  T key;
  Node l, r;

  this(T key)
  {
    this.key = key;
  }

  void insert(T val)
  {
    if (val < key) {
      if (l is null) l = new Node(val);
      else l.insert(val);
    } else {
      if (r is null) r = new Node(val);
      else r.insert(val);
    }
  }

  bool find(T val)
  {
    if (key == val) {
      return true;
    } else if (val < key) {
      if (l is null) return false;
      else return l.find(val);
    } else {
      if (r is null) return false;
      else return r.find(val);
    }
  }

  void inorderWalk()
  {
    if (l !is null) l.inorderWalk;
    write(" ", key);
    if (r !is null) r.inorderWalk;
  }

  void preorderWalk()
  {
    write(" ", key);
    if (l !is null) l.preorderWalk;
    if (r !is null) r.preorderWalk;
  }
}

