        def __init__(self, n):
            self.num = n
            self.parent = -1
            self.right = None
            self.left = None


    def __init__(self):
        self.root = None


    def insert(self, n):
        if not self.root:
            node = self.Node(n)
            self.root = node
        else:
            current, parent = self.root, None
            while current:
                parent = current
                if n < current.num:
                    current = current.left
                else:
                    current = current.right
            node = self.Node(n)
            node.parent = parent
            if n < parent.num:
                parent.left = node
            else:
                parent.right = node


    def find(self, n):
        if not self.root:
            return None
        current = self.root
        while current:
            if current.num == n:
                print('yes')
                return 
            elif n < current.num:
                current = current.left
            else:
                current = current.right
        print('no')

