    self.right = None

class BinaryTree:
  def __init__(self):
    self.root = Node(None)

  # usage
  # btree.insert(btree.root, n)
  def insert(self, node, n):
    if node.label == None:
      node.label = n
    elif n < node.label:
      if node.left == None:
        node.left = Node(n)
      else:
        node.left = self.insert(node.left, n)
    else:
      if node.right == None:
        node.right = Node(n)
      else:
        node.right = self.insert(node.right, n)
    return node

  # usage
  # btree.printer(btree.root)
  def printer(self, node):
    labels = []
    if node.left != None:
      labels.extend(self.printer(node.left))
    labels.append(node.label)
    if node.right != None:
      labels.extend(self.printer(node.right))
    return labels

  # usage
  # btree.printer_c(btree.root)
  def printer_c(self, node):
    labels = []
    labels.append(node.label)
    if node.left != None:
      labels.extend(self.printer_c(node.left))
    if node.right != None:
      labels.extend(self.printer_c(node.right))
    return labels

  def find(self, node, x):
    if node == None:
      return False
    elif node.label == x:
      return True
    elif x < node.label:
      return self.find(node.left, x)
    elif node.label < x:
      return self.find(node.right, x)

